    val grammar: List<GrammarRule> by lazy { listOf(
        GrammarRule("gid-01", TargetLang.ID, "بناء الجملة: فاعل + فعل + مفعول — بلا تصريف أبدًا", "أكبر نعمة للمتعلم: الفعل لا يتغير بالزمن ولا بالشخص. الزمن بكلمة قبل الفعل.", "[فاعل] sudah/sedang/akan [فعل] [مفعول]", listOf("Saya jual baju — أنا أبيع ملابس (دائمًا)\nSaya sudah jual baju — بعتُ الملابس\nSaya akan jual baju — سأبيع الملابس\nSedang jual sekarang — يبيع الآن"), "لا تُدخل تصريفًا عربيًا في رأسك: «jual» تصلح للأنا والأنت وهو وهم وأمس وغدًا.", Cefr.A0),
        GrammarRule("gid-02", TargetLang.ID, "«nya» — الهاء واللام في حرف واحد", "أداة التعريف والملكية والتوكيد الأولى في اللغة، ملصقة بآخر الكلمة.", "كلمة + nya = الـ/ـه/ـها", listOf("Harga**nya** berapa? — كم **سعرُه**؟\nBarang**nya** sudah datang — **البضاعة** وصلت\nBuka**nya** jam sembilan — **يُفتح** (المقصود) التاسعة"), "ترجمة «nya» دائمًا بـ«ال» تربك: إن ظهرت بعد كلمة مذكورة فهي «ه/هي» غالبًا؛ وإن كانت أول ذكر فهي تعريف.", Cefr.A0),
        GrammarRule("gid-03", TargetLang.ID, "«yang» — «الذي/التي» المفصلية", "تحول أي وصف إلى محدد: ستجدها في كل جملة اختيار بالسوق.", "yang + وصف = الذي/التي/الذي أريده", listOf("Mau **yang** mana? — أيٌّ **الذي** تريد؟\n**Yang** murah aja — **الذي** هو أرخص فقط\n**Yang** ini bagus — **هذا الذي** جيد"), "العرب يقولون «أريد الرخيص» بلا رابط — بالإندونيسية الربط بـyang إلزامي: Mau yang murah وليس Mau murah.", Cefr.A1),
        GrammarRule("gid-04", TargetLang.ID, "الوجود: ada / tidak ada (punya)", "«يوجد/عندنا/عندي» — نصف أسئلة السوق وجودية.", "Ada + شيء؟ / Tidak ada = لا يوجد · punya = يملك", listOf("Ada ukuran L? — عندكم مقاس L؟\nStok tidak ada — لا يوجد مخزون\nSaya punya dua toko — عندي متجران"), "لا تقل «Saya ada toko» بمعنى أمتلك — الصحيح punya: «ada» للوجود بالمكان و«punya» للملكية.", Cefr.A1),
        GrammarRule("gid-05", TargetLang.ID, "المبني للمجهول: di- (لغة البائع الأولى)", "التعليمات والأعمال تُبنى للمجهول: dicoba، dikirim، dibungkus.", "di + جذر الفعل = يُفعل", listOf("Sudah **dibungkus**? — **غُلّف** already؟\n**Dikirim** besok — **يُشحن** غدًا\n**Dicuci** pakai tangan — **يُغسل** يدويًا"), "لا تُربك بضم الفاعل؛ صيغة di- تُغنيك عن قول «من قام بالفعل» في 90% من خدمة البيع.", Cefr.A1),
        GrammarRule("gid-06", TargetLang.ID, "اللاحقة «-kan»: أفعل لأجلك", "خدمة المشتري كلها بهذه اللاحقة: tuliskan، ambilkan، bawakan.", "فعل + kan = نفّذه لصالح أحد", listOf("**Tuliskan** alamatnya — اكتب لي العنوان\n**Ambilkan** yang besar — أحضر لي الكبير\n**Buatkan** saya struk — أصدر لي إيصالًا"), "الفعل المجرد صحيح لكنه بارد: «tulis!» أمر جاف، «tuliskan» خدمة — في البيع الفرق ذهب.", Cefr.A1),
        GrammarRule("gid-07", TargetLang.ID, "اللاحقة «-i»: توجيه الفعل نحو هدف", "أخف أخت kan: masuki، ikuti، cuci tangannya.", "فعل + i = فعّله نحو/داخل شيء", listOf("**Ikuti** saya — اتبعني\nSudah saya **bayari** — سددتُه له\n**Masuki** lorong tiga — ادخل الممر الثالث"), "العرب يستعملون kan في كل شيء — أحيانًا i أصدق: bayar**i** (سددت له) مقابل bayar**kan** (سددت لأجله رسميًا).", Cefr.A2),
        GrammarRule("gid-08", TargetLang.ID, "«me-» الفاعلية: صانع الفعل", "الأفعال المتعدية الرسمية تبدأ بها: membeli، menjual، mengambil.", "me + جذر (تندمج بحسب أول حرف: mem/men/meng/meny)", listOf("**Membeli** langsung dari pemasok — يشتري مباشرة من المورد\n**Menjual** grosir — يبيع بالجملة\n**Mengambil** pesanan — يستلم الطلب"), "في السوق اليومي تُحذف me- غالبًا (beli بدل membeli) — لكنك ستراها في اللوحات والفواتير الرسمية فاعرفها.", Cefr.A2),
        GrammarRule("gid-09", TargetLang.ID, "«ber-»: الممارسة والحال", "berjualan (يتاجر)، berkendara (يقود) — فعل لا مفعول له.", "ber + جذر = يمارس/يكون في حال", listOf("**Berjualan** di pasar — يتاجر في السوق\nSudah **berlangganan** — صار مشتركًا/زبونًا دائمًا"), "لا تخلط ber- بـme-: berjualan يمارس البيع عمومًا، menjual يبيع شيئًا محددًا.", Cefr.A2),
        GrammarRule("gid-10", TargetLang.ID, "«ter-»: المفاجئ والأقوى والمنفذ", "terjual (نُفِذ بيعه)، termurah (الأرخص على الإطلاق)، tertipu (وقع في نصب).", "ter + وصف/فعل = الأقصى/حدث بلا قصد", listOf("Stok **terjual** habis — نفد المخزون بيعًا\n**Termurah** di kota ini — الأرخص في المدينة"), "بعض العرب يقرؤها «تر» تعجبًا فتفقد معناها — احفظها كأداة تفوّل قصوى: terbaik الأفضل نهائيًا.", Cefr.A2),
        GrammarRule("gid-11", TargetLang.ID, "«pe-/per-...-an»: أسماء الفاعل والمصادر", "منها معجم سوقك: penjual (بائع)، pembeli (مشترٍ)، pelayanan (خدمة)، perusahaan (شركة).", "pe + فعل = فاعله · per/pe + فعل + an = المصدر/المؤسسة", listOf("**Penjual** dan **pembeli** sepakat — البائع والمشتري اتفقا\n**Pelayanan** bagus — الخدمة جيدة"), "pe-/pen- حسب أول حرف الجذر (pen-j), pem-b) — لا تحفظها صمًّا؛ اربطها بالفعل الذي تعرفه.", Cefr.A2),
        GrammarRule("gid-12", TargetLang.ID, "«ke-an»: المصدر المجرد والصفات الكبرى", "kecantikan (الجمال)، kemampuan (القدرة)، kekurangan (النقص/العيب).", "ke + جذر + an = المفهوم المجرد", listOf("**Kekurangan** barang — نقص البضاعة\n**Kelebihan** harga — زيادة السعر/ميزته"), "ke-an ليست ظرفًا دائمًا؛ kelebihان مثلاً تعني ميزة وزيادة معًا — من السياق.", Cefr.A2),
        GrammarRule("gid-13", TargetLang.ID, "التكرار: جمع وتلطيف واستمرار", "ثلاث وظائف بكلمة واحدة: buku-buku كتب، pelan-pelan ببطء رفيق، jalan-jalan يتنزه.", "كلمة×2 = جمع/تلطيف/تدرج", listOf("Dilihat-**dilihat** dulu — تفرّج على راحتك (تلطيف)\nBarang-**barang** baru — بضائع جديدة (جمع)\nJalan-**jalan** ke mana? — تتنزه أين؟ (فعل مطاوع)"), "ليس كل مثنى جمعًا! Dilihat-dilihat ليس «نظرتان» — إنه تلطيف. اقرأ السياق.", Cefr.A1),
        GrammarRule("gid-14", TargetLang.ID, "حروف الجر الخمسة الكبرى", "di للمكان الثابت، ke للحركة نحو، dari المصدر، dengan بـ/مع، untuk لأجل.", "di/ke/dari/dengan/untuk + اسم", listOf("**Di** toko, **ke** pasar, **dari** gudang — في المتجر، إلى السوق، من المستودع\nBayar **dengan** kartu — ادفع بالبطاقة\nIni **untuk** kakak — هذا لكِ"), "خلط di وke أشهر خطأ عربي: «di» = يكون في، «ke» = يذهب إلى — Saya di pasar (أنا في السوق) مقابل Saya ke pasar (أنا ذاهب للسوق).", Cefr.A1),
        GrammarRule("gid-15", TargetLang.ID, "المقادير والعدّ: se- و classifiers", "se- = واحد من (sekilo كيلو، sekotak صندوق)، وdua orang (شخصان).", "se + وحدة = واحد منها · رقم + وحدة", listOf("**Sekilo** beras — كيلو أرز\nDua **orang** pembeli — زبونان (شخصان)\nTiga **lusin** — ثلاث دارزنات"), "لا تقل dua baju جمعًا عامًا في السياق الرسمي — أضف وحدة العدّ يفصح كلامك: dua helai baju (قطعتا ملابس).", Cefr.A2),
        GrammarRule("gtr-01", TargetLang.TR, "تناغم حروف العلة (2/4) — قلب التركية النابض", "اللواحق تتلون بلون حرف العلة الأول: evler (بيوت) مقابل adamlar (رجال).", "حروف أمامية e/i/ö/ü ← لواحق أمامية · خلفية a/ı/o/u ← لواحق خلفية", listOf("ev**ler**, gün**ler** — بيوت، أيام\nadam**lar**, kitap**lar** — رجال، كتب"), "لا تحفظ كل لاحقة بأشكالها؛ احفظ القاعدة وستختار الشكل تلقائيًا — وخطأ التناغم أول ما يفضح متعلمًا.", Cefr.A0),
        GrammarRule("gtr-02", TargetLang.TR, "الجمع: -ler/-lar فقط", "جمع واحد لكل الأسماء — لا مثنى ولا جمع سالم/مكسر!", "اسم + ler/lar", listOf("müşteri**ler** — زبائن\nürün**ler** — منتجات\niki müşteri — زبونان (بلا لاحقة بعد الأرقام!)"), "بعد الأرقام يبقى المفرد: «iki müşteri» لا «iki müşteriler» — أشهر خطأ عربي.", Cefr.A0),
        GrammarRule("gtr-03", TargetLang.TR, "الملكية: -im/-in/-i/-imiz/-iniz/-leri", "بدل «متجري» تقول dükkân**ım** — اللاحقة تحمل المالك كله.", "اسم + لاحقة المالك", listOf("dükkân**ım**, fiyat**ınız** — متجري، سعركم\nmasa**sı** mısın? لا: — —\nev**imiz** burada — بيتنا هنا"), "تركيب ملكية مزدوجة يتغير آخر المالك: dükkân**ın** fiyat**ı** = سعرك (الـın تظهر ثم تتحول اللاحقة الثانية) — بناء «الاسم المركب».", Cefr.A1),
        GrammarRule("gtr-04", TargetLang.TR, "var / yok — الوجود والعدم", "جملة كاملة بكلمتين: Var mı? (يوجد؟) · Yok (لا يوجد) — نصف السوق.", "شيء + var/yok", listOf("Büyük beden **var** mı? — يوجد مقاس كبير؟\nNakit **yok** — لا يوجد نقد\nVaktim **yok** — لا وقت عندي"), "var/yok تلزم الاسم المنكر غالبًا لا المعرف: «Suyum yok» (مائي غير موجود) مقابل «Su yok» (لا ماء).", Cefr.A1),
        GrammarRule("gtr-05", TargetLang.TR, "الحاضر المستمر: -iyor", "زمن «الآن» لكل الأفعال: geliyorum (آتٍ الآن).", "جذر + iyor + شخص", listOf("gel**iyor**um, gel**iyor**sun — آتي، تأتي\nsat**ıyor**uz — نبيع الآن\nTürkçe öğren**iyor**um — أتعلم التركية"), "الجذر يضعف آخره أحيانًا: git+iyor→gidiyorum (التاء ت dal) — الأفعال الشائعة تحفظ سمعيًا.", Cefr.A1),
        GrammarRule("gtr-06", TargetLang.TR, "الماضي الشاهد: -di والسماعي: -miş", "-di رأيتُه بنفسي، -miş سمعتُ به — دقة شهيرة في التركية.", "جذر + di/dı + شخص · جذر + miş + شخص", listOf("Gel**di**m, gör**düm** — جئتُ، رأيتُ (شهادة)\nGel**miş**, bozul**muş** — يقال جاء / يبدو أنه تعطل (سماع/استدلال)\nKaçmıştı fiyatlar — كانت الأسعار قد ارتفعت (قالوا)"), "العربية تفصل «ذُكر لي» — التركية تختزلها بصيغة الفعل نفسها: bozulmuş = «(يبدو أنه) تعطل».", Cefr.A1),
        GrammarRule("gtr-07", TargetLang.TR, "المستقبل: -ecek/-acak", "الوعود والخطط: yarın geleceğim (سآتي غدًا).", "جذر + ecek/acak + شخص", listOf("Gelece**ğim** — سآتي\nAlacak mısınız? — هل ستشترون؟\nKargo yarın çıkacak — الشحنة تخرج غدًا"), "cek + im تنصهر: gelecek+im → geleceğ**im** — الـk تتحول ğ عند التقاء السوابق.", Cefr.A1),
        GrammarRule("gtr-08", TargetLang.TR, "النفي: -me/-ma وللجملة «değil»", "الفعل ينفي بلاحقة والاسم بdeğil.", "جذر + me/ma (+ الزمن) · اسم + değil", listOf("gel**me**yorum — لا آتي\npahalı **değil** — ليس غاليًا\nİndirim **yok** — لا خصم (عدم وجود)"), "ثلاث طرق للنفي بلاخلط: فعل=ma/me، اسم/صفة=değil، وجود=yok.", Cefr.A0),
        GrammarRule("gtr-09", TargetLang.TR, "السؤال: mi/mı/mu/mü", "حرف يلتصق آخر الجملة ويتناغم — أشهر صوت تركي.", "جملة + mı/mi/mu/mü؟", listOf("Pahalı **mı**? — أغالي هو؟\nKart geçiyor **mu**? — تمر البطاقة؟\nAnlaştık **mı**? — اتفقنا؟"), "لا تضف mi لفعل منفي بزمن؟ استعمل الصيغة الكاملة: Gelmiyor mu? (ألا يأتي؟) — mi تلتصق بما قبلها بلا فاصل.", Cefr.A1),
        GrammarRule("gtr-10", TargetLang.TR, "الأمر والمهذب: -sin/-in/-iniz وbuyurun", "«buyurun» مقدسة، وللطلب اليومي: bak**ın** (انظروا) — واللطف بـlütfen.", "جذر + in/iniz (رسمي/جمع) · جذر (أمر مفرد مألوف)", listOf("Bak**ın**! Fiyat**a** bak**ın**! — انظروا إلى السعر!\nBuyur**un** — تفضل(وا)\nGel + lütfen — تعالَ من فضلك"), "الأمر المفرد المجرد (gel!) مع الغريب فظ — أضف in/iniz أو ابنِ جملة طلب: Gelebilir misiniz? (هل تستطيعون المجيء؟).", Cefr.A1),
        GrammarRule("gtr-11", TargetLang.TR, "القدرة: -abil والسماح: -ebilir miyim", "ödüyor**um** أدفع — öde**yebil**iyor**um** أستطيع الدفع — والسؤال ألطف طلب.", "جذر + abil/eabil + زمن", listOf("Kartla öde**yebilir** miyim? — أستطيع الدفع بالبطاقة؟\nYardım ede**bilirim** — أستطيع المساعدة\nGel**emem** — لا أستطيع المجيء"), "النفي للقدرة: -aMAm (gelemem) — الميم المضاعفة سماعية مشهورة، لا تكتب gelemiyorum بمعنى العجز.", Cefr.A2),
        GrammarRule("gtr-12", TargetLang.TR, "الوجوب: -meli/-malı", "gitsen ينبغي أن تذهب — لغة الإرشاد والنصيحة.", "جذر + meli/malı + شخص", listOf("Doktora git**meli**siniz — ينبغي أن تروا طبيبًا\nErken gel**meli**yiz — يجب أن نأتي مبكرين"), "meli ليست إلزامًا قانونيًا بل نصيحة قوية — الإلزام القاطع: zorunda ( مضطر).", Cefr.A2),
        GrammarRule("gtr-13", TargetLang.TR, "الحالات (Cases) الست — بجملة سوقية لكل حالة", "لا تحفظ جدولًا؛ احفظ جملة تشتري بها!", "yalın (مفرد) · -i (مفعول) · -e (اتجاه) · -de (مكان) · -den (من) · -in (ملكية)", listOf("Fiyat**ı** düşür — اخفض السعرَ (مفعول)\nKasaya git — اذهب إلى الكاشيرِ (اتجاه)\nDükkân**da** — في الدكانِ (مكان)\nStok**tan** düştü — نقص من المخزونِ (منبع)\nMüşteri**nin** hakkı — حق الزبونِ (ملكية)"), "المفرد النكرة لا ياخذ -i: «Fiş istiyorum» (أريد فيشت) لا «Fişi» إلا إذا عُرِف سابقًا — التمييز أهم قاعدة Cases.", Cefr.A2),
        GrammarRule("gtr-14", TargetLang.TR, "الشرط: -se/-sa — «لو» حلمًا وعرضًا", "İndirim **yaparsan** alırım = لو خفضتَ أخذت — لغة المساومة ذاتها!", "جذر + se/sa + شخص (+زمن)", listOf("İki tane **alırsan** fiyatı kırarım — لو أخذت اثنين أكسر لك السعر\nGel**se** iyi olur — لو أتى لكان حسنًا\nOlsa giderdim — لو حدث لكنت ذهبت (لم يحدث)"), "se ليست «إذا» الشرطية الجزمة العربية فقط — تغطي التمني والعرض أيضًا: Keşke gelse! (ليته يأتي!).", Cefr.B1),
    ) }
    val culture: List<CulturalNote> by lazy { listOf(
        CulturalNote("cul-01", "«Hoş geldiniz» ليست مجاملة — إنها بروتوكول", "<p>في تركيا، صمت البائع عند دخول الزبون يقارب الإهانة. <b>Hoş geldiniz</b> واجبة فورية من أي شخص داخل المحل — حتى النادل في المطبخ يرفع رأسه ليقولها. والرد عليها أيضًا إلزامي على الزبون: <b>Hoş bulduk</b> (وجدنا الخير).</p><p>لماذا تهمك؟ لأن نسيانها يجعلك «بائعًا غريبًا» فورًا في عين الزبون التركي، وذكرها يجعلك واحدًا من أهل المحل قبل أن تبيع شيئًا.</p><p class=\"mini-note\">وبالمثل <b>Kolay gelsin</b> (ليكن عملك سهلًا) تُقال لكل من تراه يعمل — أعجوبة اجتماعية تفتح قلوبًا مجانًا.</p>", false),
        CulturalNote("cul-02", "ثقافة «Maaf» و«Terima kasih» الإندونيسية — الاعتذار الاستباقي", "<p>البائع الإندونيسي المحترف يبدأ كثيرًا من الاعتذار قبل أي طلب: <b>Maaf ya kak…</b> (عذرًا طيب) قبل أن يعرض، قبل أن يسأل، قبل أن يناول. الاعتذار الاستباقي ليس ضعفًا هناك — إنه تليين للعلاقة يجعل أي طلب لاحق مقبولًا.</p><p>وكذلك الشكر المضاعف: <b>Terima kasih banyak</b> (شكرًا كثيرًا) ورد الجميل <b>Sama-sama</b>. والابتسامة — إندونيسيا أكبر بلد مسلم وأهلها يبتسمون بالفطرة؛ البائع العابس يخسر قبل أن يتكلم.</p>", false),
        CulturalNote("cul-03", "أين يُتوقع منك المساومة وأين تُحرج نفسك؟", "<p><b>إندونيسيا:</b> الأسواق التقليدية (pasar) وبسطات الشارع وأسواق الملابس — المساومة متوقعة وممتعة. أما Indomaret وAlfamart والسلاسل والمولات الحديثة — السعر ثابت تمامًا والمحاولة تُحرج. لافتات <b>HARGA PAS</b> تعني «سعر ثابت» و<b>NEGO</b> تعني «تفاوض».</p><p><b>تركيا:</b> البازارات السياحية والأسواق الشعبية (pazar) — مساومة كاملة، بل غيابها يرفع السعر عليك. المولات والصيدليات والمتاجر الرسمية — الأسعار ثابتة بالفيشت.</p><p><b>قاعدة ذهبية:</b> كلما كان البائع «صاحب البضاعة نفسه» والمكان مزدحمًا بالبضائع، زاد احتمال التفاوض.</p>", false),
        CulturalNote("cul-04", "آلة الحاسبة وقراءة الأرقام على الشاشة", "<p>في تركيا آلة الحاسبة عضو رسمي في طاقم البيع: عند أي تفاوض يدفع البائع الرقم ويدير الشاشة نحوك، وتكتب ردك وترجعها. هذا يوفر على الجميع أخطاء النطق في الأرقام — تعلّم قراءة الأرقام بسرعة على الشاشة فهي مهارة سوق حقيقية.</p><p>في إندونيسيا تفعل الشيء نفسه مع الزبائن الأجانب، ويستخدم الباعة أصابع اليد لل أرقام الصغيرة. <b>تنبيه إشارات:</b> الإندونيسيون يشيرون بإبهام اليد لا بالسبابة عند توجيه الزبون («di sana» = هناك) — السبابة الممدودة نحو شخص تعد وقحة.</p>", false),
        CulturalNote("cul-05", "اليد اليمنى فقط: تناول وإعطاء الإندونيسي", "<p>في إندونيسيا، تعطي وتستلم النقود والبضاعة <b>باليد اليمنى دائمًا</b>، أو باليمنى مع لمس اليسرى لها (إشارة احترام مزدوجة). إعطاء الزبون نقوده باليسرى وحدها يُقرأ سوء أدب وإن لم يعلق أحد.</p><p>في تركيا الأمر أخف، لكن اليد اليمنى تبقى الأصل في المصافحة والمعاملة، ولا تصفق بيدك على يد أحد في حديث تجاري (قد تفهم موافقة!).</p>", false),
        CulturalNote("cul-06", "متى تنتقل من «siz» إلى «sen»؟ (تركيا)", "<p>التركية تحدد العلاقة كلها بكلمة واحدة: <b>siz</b> (أنتم/رسمي) أو <b>sen</b> (أنت/حميم). القاعدة التجارية: ابدأ دائمًا بـsiz مع أي زبون. الانتقال إلى sen يحدث حين <b>هو</b> يبادر — «abi sen yap» (اقلبها أنت يا أخي) — عندها الصداقة فُتحت لك فلا تتأخر.</p><p>استخدام sen مع كبير في السن أو زبون رسمي أول مرة = حماقة تُغتفر للأجنبي لكنها تُنسى لمن يجيد التركية. كن على الجانب الرسمي دائمًا حتى تُدعى لغيره.</p><p class=\"mini-note\">الإندونيسية أسهل: بلا siz/sen — لكن مخاطبة <b>kamu</b> (أنت الحميمة) للزبائن خطأ عربي شائع! استعمل kak/mbak/mas/Bu/Pak كما في فصل المخاطبات.</p>", false),
        CulturalNote("cul-07", "اقرأ «الأسعار المختصرة» قبل أن تدفع", "<p>أشهر فخ يقع فيه العرب بإندونيسيا: البائع يقول <b>«Seratus»</b> (مئة) وهو يقصد <b>مئة ألف</b>! في السوق تُحذف «ribu» (ألف) لأنها مفهومة. القاعدة: عند سماع رقم، كرّره كاملًا للتأكيد: <b>«Seratus ribu?»</b> (مئة ألف؟) — فيرد بتأكيد أو تصحيح. لا أحد يعتبرك غبيًا؛ الجميع يفعلها.</p><p>وفي تركيا: <b>«On lira elli»</b> تعني 10.50 (عشرة ليرات وخمسين قرشًا) — الفيش يوضح دائمًا. وأسعار «virgül» (الفاصلة العشرية) تُكتب بفاصلة: 10,50.</p>", false),
        CulturalNote("cul-08", "إيقاع اليوم الديني — نظّم بيعك عليه", "<p><b>إندونيسيا:</b> صلاة الجمعة تعطل الأسواق تقريبًا 11:30–13:00 في المناطق المتدينة، ورمضان يقلب ساعات الذروة (الذروة قبل الإفطار وبعده) — و<b>Selamat berpuasa</b> (صومًا مقبولًا) تحية تفتح القلوب طوال الشهر. عيد الفطر (Hari Raya/Lebaran) أعلى موسم هدايا وملابس في السنة.</p><p><b>تركيا:</b> الجمعة أيضًا ساعة الذروة تنخفض وقت الصلاة، والأعياد (bayram) موسم هدايا أسطوري — وتحية <b>İyi bayramlar</b> واجبة المعرفة لكل بائع. رمضان التركي موسم «pide» والحلويات، والباعة يجهزون باكرًا.</p>", false),
        CulturalNote("cul-09", "«Bonus» الإندونيسية: الهدية الصغيرة أقوى من الخصم", "<p>في إندونيسيا، ثقافة <b>bonus</b> (بونوس) عريقة: الزبون الذي يساوم يسعد أكثر بقطعة إضافية صغيرة (شماغ، جراب، قطعة نثر) من خصم نقدي مساوٍ. لماذا؟ لأن الخصم يُنسى والهدية تُحكى وتُعرض — إنها تسويق مجاني بكلفة قرشين.</p><p>في تركيا المعادل: <b>«bu da benden»</b> (وهذه من عندي) عند الدفع — جملة الود التي ينتظرها الزبون التركي ولو كانت حلوى صغيرة. وكوبون الشاي/القهوة في الصفقات الكبيرة جزء من الطقس.</p>", false),
        CulturalNote("cul-10", "أخطاء العرب الشائعة في السوقين (لا تفعلها)", "<ul>\n<li><b>«kamu» للزبون الإندونيسي</b> — مخاطبة طفل أو حبيب، لا زبون. استعمل kak/mbak/mas.</li>\n<li><b>قراءة c كـ«س/ك»</b> — cinta ليست «سِنتا» بل «تشينتا». كارثة الإندونيسية رقم واحد.</li>\n<li><b>التركية c كـ«ك/س»</b> — canım ليست «كانيم» خطأ… بل هي «جانيم» — c = ج دائمًا.</li>\n<li><b>«sen» للتركي الكبير</b> أول مرة — ابدا بـsiz دائمًا.</li>\n<li><b>المساومة في السلاسل والمولات</b> — يُحرج البائع الموظف الذي لا يملك القرار أصلًا.</li>\n<li><b>رفع الصوت عند سوء الفهم</b> — البطء يزيد الفهم والصوت يزيد التوتر فقط.</li>\n<li><b>تجاهل «Hoş geldiniz»</b> — لا تقف صامتًا عند دخول زبون تركي.</li>\n<li><b>الإشارة بالسبابة للناس بإندونيسيا</b> — استعمل الإبهام أو كف اليد المفتوح.</li>\n<li><b>إعطاء/استلام باليسرى بإندونيسيا</b> — يمنى دائمًا.</li>\n</ul>", false),
        CulturalNote("cul-11", "الدفع الرقمي: QRIS في إندونيسيا والبطاقة في تركيا", "<p><b>إندونيسيا:</b> <b>QRIS</b> نظام الدفع الموحد بمسح كود QR — حتى بسطات الشارع تعلّق رمزها. «Bayar QRIS ya kak» جملة يومية. أقل عمولة من البطاقات، لذا الباعة يفضلونه. GoPay/OVO/DANA هي المحافظ الشهيرة.</p><p><b>تركيا:</b> البطاقات البنكية ملك (تقريبًا كل شيء يقبلها حتى التاكسي)، والأقساط بالبطاقة (taksit) ثقافة قومية — «peşin fiyatına 9 taksit» صياغة يجب أن يفهمها كل بائع. النقود مقبولة لكن الفيش الإلزامي (ÖKC) قانوني حتى في أقل المحلات.</p>", false),
        CulturalNote("cul-12", "«Jam karet» — الساعة المطاطية وسلّم الصبر", "<p>«Jam karet» (ساعة المطاط) تعبير إندونيسي عن المواعيد المرنة: «besok» (غدًا) قد تعني بعد غد، و«sebentar» (لحظة) قد تعني عشرين دقيقة. لا تنفجر — خطط هامشًا زمنيًا وذكّر بلطف: <b>«Janji ya kak, jam berapa pasti?»</b> (وعد مني: الساعة كم بالضبط؟).</p><p>في تركيا الدقة أعلى في المدن الكبرى، لكن «yarın gelir» (يأتي غدًا) عند الصناعيين والأسواق الشعبية يحتاج نفس التذكير الودي. القاعدة التجارية الناجحة في البلدين: <b>وعود صغيرة محققة أفضل من وعود كبيرة مؤجلة</b>.</p>", false),
        CulturalNote("cul-13", "هدية العينة والزبون الأول — اقتصاد الجيرة", "<p>في كلا الثقافتين، «امتنان» السوق اقتصاد حقيقي: زبون أول تُعطيه قطعة صغيرة «للتجربة»، أو خصم افتتاح — سيعود ومعه أقاربه. الإندونيسيون يقولون <b>«coba dulu»</b> (جرّب أولًا) ويقصدون بها بناء علاقة لا مجرد تسويق.</p><p>وفي تركيا: تقديم الشاي للزبون في صفقة كبيرة (çay ikramı) ليس مضيعة وقت — إنه الطقس الذي تُبرم فيه العقود. لا تستعجل: اشرب الشاي وتكلم عن العائلة ثلاث دقائق ثم افترسا السعر.</p>", false),
        CulturalNote("cul-14", "قانون الثقة: «الزبون يشتري البائع قبل البضاعة»", "<p>في إندونيسيا كلمة <b>«rezeki»</b> (رزق) تسمعها من كل بائع: الزبون رزق مرسل لا «هدف مبيعات». هذا التصور يغيّر لغة الجسد كلها: صبر على المتفرج، سماح في المساومة، وداع دافئ لمن لم يشترِ.</p><p>وفي تركيا المثل الشعبي التجاري: <b>«Müşteri herzamandır kral»</b> — الزبون ملك دائمًا، والأهم: البائع الذي «يبيع بلا حيلة» (dürüst satıcı = البائع الأمين) تُبنى له سمعة في الحي كله خلال أسابيع.</p><p><b>خلاصة عملية:</b> جملة واحدة صادقة («هذا لا يناسبك، خذ الأرخص») تجلب لك عشرة زبائن — هذه أهم استثمارات السوقين.</p>", false),
    ) }
    val dialogues: List<Dialogue> by lazy { listOf(
        Dialogue("sit-shop1", "دخول زبونة إلى محل ملابس (إندونيسيا)", "امرأة شابة (تُخاطَب mbak) تدخل محل ملابس صغيرًا في جاكرتا. أنت البائع.", Cefr.A1, listOf(DialogueTurn("S", "أهلًا وسهلًا! تفضلي شوفي على راحتك.", "Selamat datang, mbak! Silakan dilihat-dilihat dulu.", "Hoş geldiniz! Rahatça bakabilirsiniz."),DialogueTurn("C", "شكرًا. أتفرج فقط.", "Makasih. Lihat-lihat dulu aja.", "Teşekkürler. Önce bir bakayım."),DialogueTurn("S", "تمام، لا مشكلة. أنا هنا لو احتجتِ شيئًا.", "Tidak apa-apa. Kalau butuh, panggil saja ya.", "Sorun değil. İhtiyacınız olursa seslenin."),DialogueTurn("C", "هذا الفستان كم سعره؟", "Dress yang ini berapa?", "Bu elbise kaç lira?"),DialogueTurn("S", "هذا 250 ألفًا. وصل أمس، وموجود بثلاثة ألوان.", "Yang ini dua ratus lima puluh, mbak. Baru kemarin datang, ada tiga warna.", "Bu iki yüz elli. Dün geldi, üç rengi var."),DialogueTurn("C", "أجرب فيه؟", "Boleh dicoba?", "Deneyebilir miyim?"),DialogueTurn("S", "طبعًا! غرفة القياس هناك. خذي مقاس M أولًا.", "Boleh banget! Kamar pas di situ. Ambil ukuran M dulu ya.", "Tabii! Orada deneme kabini. Önce M bedeni alın."),DialogueTurn("C", "(بعد القياس) المقاس مضبوط لكن اللون…", "Pas badannya, tapi warnanya…", "Bedenim oldu ama rengi…"),DialogueTurn("S", "عندي نفس الموديل بالأسود — لونكِ الآمن! أجريبه؟", "Ada model yang sama warna hitam. Silakan coba sekalian.", "Aynı modelin siyahı da var, deneyin isterseniz."),DialogueTurn("C", "أسود أحسن! آخذه. مع كيس من فضلك.", "Hitam lebih bagus. Saya ambil. Kantongnya sekalian ya.", "Siyah daha iyi. Alıyorum. Poşet de alın lütfen."),DialogueTurn("S", "ممتاز! نقدًا أم QRIS؟", "Sip, mbak! Bayar tunai atau QRIS?", "Harika! Nakit mi, kart mı?"),DialogueTurn("C", "QRIS. تفضلي.", "QRIS ya. Ini.", "Kartla. Buyurun."),DialogueTurn("S", "تم الدفع. هذا إيصالك — احتفظي به للاستبدال خلال 3 أيام. تعالي دائمًا!", "Sudah lunas. Ini struknya, simpan ya buat tukar tiga hari. Dateng lagi ya, mbak!", "Ödeme tamam. Fişiniz buysun, üç gün içinde değişim hakkı. Yine bekleriz!"))),
        Dialogue("sit-bargain-id", "مساومة في سوق جاكرتا الشعبي", "زبون (تخاطبه kak) أمام بسطة حقائب في سوق تقليدي (pasar). الأسعار قابلة للتفاوض (bisa nego).", Cefr.A1, listOf(DialogueTurn("C", "هذه الحقيبة كم؟", "Tas yang ini berapa, bang?", "Bu çanta kaç para abi?"),DialogueTurn("S", "هذه الجلد الأصلي، 300 ألف يا أخي.", "Ini kulit asli, bang. Tiga ratus.", "Bu hakiki deri, üç yüz abi."),DialogueTurn("C", "300؟! غالي جدًا!", "Tiga ratus?! Mahal bang!", "Üç yüz mü? Çok pahalı!"),DialogueTurn("S", "رخيص أصلًا! انظر للخياطة. كم تعطي؟", "Sudah murah itu! Lihat jahitannya. Berani kasih berapa?", "Ucuz bile diyebilirim, dikişine bakın. Kaç veriyorsunuz?"),DialogueTurn("C", "أعطيك 200 ولا زيادة.", "Dua ratus, nggak lebih.", "İki yüz, daha fazla yok."),DialogueTurn("S", "200 مؤلم جدًا! أقل شيء 280.", "Dua ratus sakit banget, bang! Paling kurang dua ratus delapan puluh.", "İki yüz çok az! En fazla iki yüz seksen inerim."),DialogueTurn("C", "خلّينا نلتقي في المنتصف: 250 وخلصنا.", "Ketemu tengahnya aja: dua ratus lima puluh, deal.", "Ortada buluşalım: iki yüz elli, tamam mı?"),DialogueTurn("S", "250؟ حسنًا لكن بشرط — تأخذ المحفظة معها بـ50.", "Dua ratus lima puluh? Ya sudah, tapi sekalian dompetnya lima puluh.", "İki yüz elli mi? Peki, yanına cüzdanı elli liraya veririm."),DialogueTurn("C", "خلاص، اتفقنا! نقدًا.", "Sip, deal bang! Ini uangnya.", "Tamam, anlaştık! Paranız."),DialogueTurn("S", "صفقة! خذها بالصحة — وعُد تخبرنا برأيك فيها!", "Sip! Saya bungkus ya. Makasih banyak, bang! Dateng lagi ya!", "Anlaştık! Paketliyorum. Çok teşekkürler abi, yine bekleriz!"))),
        Dialogue("sit-bargain-tr", "مساومة في البازار التركي (إسطنبول)", "زبون أمام دكان سجاد في بازار سياحي. المساومة (pazarlık) متوقعة وممتعة. يُستخدم الحاسبة كثيرًا.", Cefr.A1, listOf(DialogueTurn("S", "تفضل! أهلًا بك — من إيران؟ من سوريا؟ على أي حال، أهلًا! انظر لهذه.", "Silakan! Coba lihat permadani yang ini.", ""),DialogueTurn("C", "كم هذه السجادة؟", "Permadani ini berapa?", "Bu halı kaç lira?"),DialogueTurn("S", "هذه حرير يدوي من كايْسري — 5000 ليرة.", "", "Bu el işi Kayseri halısı, beş bin lira."),DialogueTurn("C", "5000؟! كثيرة عليّ. أستطيع 3000.", "", "Beş bin mi? Çok buldum. Üç bin verebilirim."),DialogueTurn("S", "3000؟ يا أخي حرير هذا! على الأقل 4500 — انظر العقد.", "", "Üç bin mi olur abi, ipek bu! En az dört bin beş yüz. Düğümüne bakın."),DialogueTurn("C", "ما رأيك: 4000 وآخذ معها الوسادة الصغيرة؟", "", "Peki: dört bin, bir de yastığı küçüğü beraber."),DialogueTurn("S", "4000 مع الوسادة؟ استراحة الشاي أولًا! …حسنًا: 4200 مع الوسادة، وأصلي لك القهوة.", "", "Dört bin ve yastık mı? Çay molası verelim! …Tamam: dört bin iki yüz, yastık da benden, çay da benden."),DialogueTurn("C", "اتفقنا! 4200 بالبطاقة ممكن؟", "", "Anlaştık! Kartla olur mu?"),DialogueTurn("S", "بطاقة؟ 4200 نقدي، وبالبطاقة 4400 — العمولة يا صديقي. قهوتك في الطريق!", "", "Kart mı? Peşin dört bin iki yüz, kartla dört bin dört yüz — komisyon canım. Çayınız geliyor!"),DialogueTurn("C", "نقدًا إذن. هذه لك.", "", "O zaman peşin. Buyurun."),DialogueTurn("S", "مبروك عليك! تستاهل بيتها. استخدمها بالصحة — وعُد تسلّم!", "", "Hayırlı olsun, evine yakışacak. Güle güle kullanın, yine bekleriz!"))),
        Dialogue("sit-complaint-tr", "زبون غاضب: منتج معيب والاستبدال (تركيا)", "زبون يعيد خلاطًا كهربائيًا توقف بعد يومين. الغضب واضح. الفيشت معه.", Cefr.A1, listOf(DialogueTurn("C", "هذا توقف عن العمل! يومان فقط! لم أدفع لأحصل على خردة!", "", "Bu bozuldu! Daha iki gün oldu! Hurdaya para vermedim ben!"),DialogueTurn("S", "أتفهمك تمامًا. من حقك أن تغضب — أنا أسمعك.", "", "Haklısınız, kesinlikle. Öfkenizi anlıyorum, dinliyorum."),DialogueTurn("C", "الفيشت معي. أريد حقي: جهاز يعمل أو نقودي.", "", "Fişim de yanımda. Hakkımı istiyorum: çalışan bir makine ya da param."),DialogueTurn("S", "تمامًا. لأتأكد فهمت: عمل يومين ثم توقف كليًا؟", "", "Peki, teyit edeyim: iki gün çalıştı, sonra tamamen durdu, öyle mi?"),DialogueTurn("C", "بالضبط. توقف كليًا.", "", "Aynen öyle. Tamamen durdu."),DialogueTurn("S", "أعتذر بصدق. أمامك خياران، وقرارك أمر: استبدال فوري بجديد، أو استرجاع كامل. أيهما يريحك؟", "", "Gerçekten özür dileriz. İki seçenek sunuyorum, kararınız: hemen yenisiyle değişim ya da para iadesi. Hangisi size iyi gelir?"),DialogueTurn("C", "…أريد جهازًا جديدًا يعمل. وأريد فحصه أمامي.", "", "Yenisi olsun, ama gözümün önünde test edelim."),DialogueTurn("S", "طلب عادل تمامًا. (يختبره) اسمع المحرك — سليم. سأمدد ضمانك من اليوم أيضًا.", "", "Çok haklısınız. (test eder) Duyun motoru — sağlam. Garantinizi de bugünden itibaren uzatıyorum."),DialogueTurn("C", "حسنًا… شكرًا. اعتذرت فأنقذت موقفي.", "", "Peki… teşekkürler. Özür dileyince mesele kalmadı."),DialogueTurn("S", "شكرًا لصبرك وسعة صدرك. أنت زبوننا منذ سنوات — وستبقى. مع السلامة، وبالصحة!", "", "Sabrınız ve anlayışınız için teşekkürler. Yıllardır müşterimizsiniz, öyle kalın. Güle güle, hayırlı olsun!"))),
        Dialogue("sit-rush-id", "زبون مستعجل (إندونيسيا)", "زبون يهب داخل المحل ناظرًا ساعته: يريد قميص هدية عاجلة قبل حفل. الوقت ضيق.", Cefr.A1, listOf(DialogueTurn("C", "بسرعة رجاءً! عندي 5 دقائق — أريد قميصًا هدية لصديقي.", "Cepet ya kak! Lima menit lagi — mau kemeja buat hadiah teman.", "Çabuk olur musunuz, beş dakikam var — arkadaşıma hediye gömlek."),DialogueTurn("S", "فهمت! مقاسه تقريبًا؟ ولونه المفضل؟", "Siap! Ukurannya kira-kira? Warna favoritnya?", "Anladım! Bedeni kaç civarı, rengi ne olsun?"),DialogueTurn("C", "مقاسي تقريبًا. أزرق أو أسود.", "Kayak punya saya. Biru atau hitam.", "Benimle aynı. Mavi ya da siyah."),DialogueTurn("S", "(يضع خيارين على الطاولة) هذان أسرع مبيعًا لدينا. هذا 180 وهذا 250 — ذاك أجود قماشًا.", "Ini dua yang paling laris. Yang ini seratus delapan puluh, yang ini dua ratus lima puluh — bahannya lebih bagus.", "İki en çok satanımız: bu yüz seksen, şu iki yüz elli — şu daha kaliteli kumaş."),DialogueTurn("C", "أخذ الأجود. غلاف هدية ممكن؟", "Ambil yang bagus. Bungkus kado bisa?", "Kaliteli olanı alayım. Hediye paketi olur mu?"),DialogueTurn("S", "فورًا! (يغلّف) نقدًا أم بطاقة؟", "Bisa! (membungkus) Bayar tunai atau kartu?", "Hemen! (paketler) Nakit mi kart mı?"),DialogueTurn("C", "بطاقة. تفضل.", "Kartu. Ini.", "Kart. Buyurun."),DialogueTurn("S", "تم! هذا إيصالك والفيشت. وعيد سعيد لصديقك!", "Sudah! Ini struknya. Selamat ya buat temannya!", "Tamamdır! Fişiniz burada. Arkadaşınız bayramını kutlasın!"),DialogueTurn("C", "شكرًا على سرعتك! مثالي.", "Makasih cepatnya! Mantap.", "Hızınız için teşekkürler, mükemmeldi!"))),
        Dialogue("sit-wholesale", "تفاوض مع مورد على سعر جملة (إندونيسيا)", "أنت صاحب محل، تتفاوض مع مورد (pemasok) على توريد 200 قطعة قمصان شهريًا. المحادثة في مكتب المورد.", Cefr.A1, listOf(DialogueTurn("C", "أعجبتني عيناتكم. أتكلم عن 200 قطعة شهريًا — دائمة.", "Sampelnya bagus. Saya bicara dua ratus potong per bulan — rutin.", ""),DialogueTurn("S", "أهلًا بك شريكًا! سعر الجملة للقطعة 85 ألفًا، والحد الأدنى 100 قطعة.", "Selamat datang partner! Harga grosir per potong delapan puluh lima. Minimum seratus potong.", ""),DialogueTurn("C", "85؟ السوق يعرض 78. أستطيع التعامل بكميات أكبر مقابل 75.", "Delapan puluh lima? Pasar kasih tujuh puluh delapan. Kalau jumlah lebih besar, saya minta tujuh puluh lima.", ""),DialogueTurn("S", "75 مستحيل — التكلفة فوقها. لكن عند 200 شهريًا: 80، وأحمل لك التوصيل داخل المدينة.", "Tujuh puluh lima tidak mungkin, modal saja lebih. Tapi kalau dua ratus rutin: delapan puluh, ongkir dalam kota saya tanggung.", ""),DialogueTurn("C", "أقترح 78 وتدفع أنت التوصيل — وأتعهد بـ250 شهريًا لأربعة أشهر.", "Kita sepakat tujuh puluh delapan, ongkir dari kakak. Saya komit dua ratus lima puluh per bulan, empat bulan.", ""),DialogueTurn("S", "250 لأربعة أشهر… حسنًا: 78. لكن الدفع نصف مقدم ونصف عند الاستلام.", "Dua ratus lima puluh empat bulan… ya sudah: tujuh puluh delapan. Tapi bayar setengah DP, setengah waktu barang sampai.", ""),DialogueTurn("C", "موافق، بشرط: استبدال أي صنف معيب خلال 14 يومًا.", "Sepakat, asal: barang cacat bisa retur empat belas hari.", ""),DialogueTurn("S", "اتفقنا. سأرسل لك الاتفاق والفاتورة واتساب. أول شحنة متى تريدها؟", "Deal. Nanti saya kirim perjanjian sama faktur lewat WA. Kiriman pertama mau kapan?", ""),DialogueTurn("C", "الأسبوع القادم. تم التعامل — نتشارك الربح إن شاء الله.", "Minggu depan. Deal — semoga kita sama-sama untung.", ""))),
        Dialogue("sit-foreign-tr", "زبون أجنبي لا يتكلم التركية جيدًا", "سائح أجنبي في محل هدايا بأنطاليا. تركيته ضعيفة. أنت البائع.", Cefr.A1, listOf(DialogueTurn("C", "مرحبًا… كم… هذا؟ (يشير لطبق)", "", "Merhaba… bu… kaç?"),DialogueTurn("S", "500 ليرة. (يكتب على الآلة الحاسبة ويدورها له)", "", "Beş yüz. (hesap makinesine yazıp gösterir)"),DialogueTurn("C", "كثير؟ ناقص؟ (بحركة يدين متقابلتين)", "", "Çok mu? İndirim olur mu?"),DialogueTurn("S", "(يبتسم ويكتب 450) صديقي… 450. آخر سعر.", "", "(gülümser, 450 yazar) Arkadaşım, dört yüz elli. Son fiyat."),DialogueTurn("C", "طبقان… 800؟ (يرفع إصبعين)", "", "İki tane… sekiz yüz?"),DialogueTurn("S", "طبقان… 850. جيد جدًا! (يكتبها ويصافح)", "", "İki tane dört yüz ellişer — sekiz yüz elli. Çok iyi!"),DialogueTurn("C", "تمام! نعم. (يخرج بطاقته)", "", "Tamam, evet. (kartını uzatır)"),DialogueTurn("S", "بطاقة ممكن. هذه فتحة البطاقة… نعم هنا. إيصالك — مهم للجمارك!", "", "Kart olur. Fişiniz — gümrük için önemli!"),DialogueTurn("C", "شكرًا جزيلًا! وداعًا!", "", "Çok teşekkürler! Güle güle!"),DialogueTurn("S", "مع السلامة! سفرك موفقًا!", "", "Güle güle, iyi yolculuklar!"))),
        Dialogue("sit-hesitant-id", "زبونة مترددة بين خيارين (إندونيسيا)", "زبونة تحير بين حقيبتين لونين متقاربين منذ عشر دقائق. تحتاج قائدًا لا بائعًا.", Cefr.A1, listOf(DialogueTurn("C", "لا أعرف أيهما آخذ… كلاهما جميل.", "Bingung mau pilih yang mana… dua-duanya bagus.", "Hangisini alsam bilemedim… ikisi de güzel."),DialogueTurn("S", "أفهمك! سؤال يساعدك: للأمسيات أم للاستخدام اليومي؟", "Saya ngerti! Biar mudah: buat acara malam atau buat harian?", "Sizi anlıyorum! Kolaylaştıralım: akşam için mi, günlük mü?"),DialogueTurn("C", "للاستخدام اليومي غالبًا… مع الجامعة.", "Harian sih… ke kampus juga.", "Genelde günlük… üniversiteye de."),DialogueTurn("S", "إذن نصيحتي: هذا — جلده أدوم واللون لا يتوسخ بسرعة. ولو كنت مكانك لأخذته.", "Berarti saran saya: yang ini. Kulitnya lebih awet, warnanya nggak gampang kotor. Kalau saya sih ambil yang ini.", "O zaman önerim bu: derisi daha dayanıklı, rengi kolay kir tutmaz. Ben olsam bunu alırdım."),DialogueTurn("C", "لكن ذاك أرخص بـ50 ألفًا…", "Tapi yang itu lebih murah lima puluh ribu…", "Ama öteki elli bin daha ucuz…"),DialogueTurn("S", "صحيح. لكن فرق 50 سيدفعه معك أول تنظيف — ذاك يتوسخ بسرعة. على سنة كاملة هذا أوفر.", "Betul. Tapi selisih lima puluh itu habis di pencucian pertama — yang itu cepat kotor. Setahun dihitung, yang ini lebih hemat.", "Doğru, ama farkı ilk temizlemede ödersiniz — öteki çabuk kirlenir. Yıllık hesapta bu daha ekonomik."),DialogueTurn("C", "(تضحك) أقنعتني! آخذ الذي نصحت به.", "(tertawa) Yaudah, saya ikut saran kakak!", "(güler) Pekâlâ, tavsiyenize uyuyorum!"),DialogueTurn("S", "اختيار موفق! ولم تعجبي خلال أسبوع نبدله لك — بلا نقاش.", "Pilihan tepat! Kalau dalam seminggu kurang cocok, tukar saja — tanpa ribet.", "Doğru seçim! Bir hafta içinde beğenmezseniz değiştiririz, sorunsuz."),DialogueTurn("C", "رائع! أدفعه QRIS.", "Mantap! Bayar QRIS ya.", "Harika! Kartla ödeyeyim."))),
        Dialogue("sit-complaint-id", "خطأ في طلب موصَّل — الاسترجاع (إندونيسيا)", "زبونة استلمت طردًا فيها قميص رجالي بدل الفستان الذي طلبته عبر واتساب. غاضبة لكن مهذبة. الخطأ من قسم التجهيز.", Cefr.A1, listOf(DialogueTurn("C", "أختي، هذا ليس طلبي! طلبت فستانًا وأرسلتم قميصًا رجاليًا!", "Kak, ini bukan pesanan saya! Saya pesan dress, kok yang datang kemeja cowok!", "Bu benim siparişim değil! Elbise istemiştim, erkek gömleği gelmiş!"),DialogueTurn("S", "حقك معي أختي، هذا خطؤنا فعلًا. أعتذر بصدق — دعيني أتأكد من طلبك.", "Kakak benar, ini salah kami. Maaf sekali. Saya cek dulu ya pesanannya.", "Haklısınız, bizim hatamız. Çok özür dileriz, siparişinizi kontrol edeyim."),DialogueTurn("C", "الطلب رقم 1122: فستان أخضر مقاس M. عندي صورة المحادثة.", "Pesanan 1122: dress hijau ukuran M. Screenshot chatnya saya simpan.", "Sipariş 1122: yeşil elbise, M beden. Yazışmanın ekran görüntüsü bende."),DialogueTurn("S", "صحيح، الخطأ واضح. أمامك خياران: نستبدله اليوم والجديد يصل غدًا، أو نرد مالك كاملًا اليوم. من حقك أيهما.", "Betul, jelas salah kami. Ada dua pilihan: saya tukar hari ini, besok pagi sampai. Atau uang kembali hari ini juga. Kakak berhak pilih.", "Evet, hatayı görüyorum. İki seçenek: bugün değişim, yenisi yarın elinizde; ya da bugün para iadesi. Sizin seçiminiz."),DialogueTurn("C", "لا أريد الانتظار. أرجعوا لي مالي. وتفضلوا باستلام القميص.", "Nggak mau nunggu. Uangnya dikembalikan saja. Kemejanya nanti diambil.", "Beklemek istemiyorum. Paramı iade edin, gömleği alın geri."),DialogueTurn("S", "تمام. سأرد 195 ألفًا الآن إلى حسابك، والحمّال يمر على القميص اليوم. عذرًا مرة أخرى على تشويش يومك.", "Baik. Seratus sembilan puluh lima saya kembalikan sekarang ke rekening kakak. Kurirnya hari ini ambil kemejanya. Maaf sekali lagi sudah merepotkan.", "Peki. İadeyi hemen yapıyorum, kurye bugün gömleği alsın. Tekrar özür dileriz, sizi uğraştırdık."),DialogueTurn("C", "وصل المبلغ. شكرًا على سرعة المعالجة — هكذا تُحل المشاكل.", "Uangnya sudah masuk. Makasih cepatnya. Begini cara masalah diselesaikan.", "Para hesaba geçti. Hızınız için teşekkürler, sorun böyle çözülür."),DialogueTurn("S", "شكرًا لتفهمك أختي. وعندك خصم 10% على طلبك القادم عندنا — نستحق فرصة تصحيح الانطباع.", "Makasih pengertiannya kak. Ada diskon sepuluh persen buat pesanan kakak berikutnya. Kami berhak diberi kesempatan memperbaiki.", "Anlayışınız için teşekkürler. Sonraki siparişinize yüzde on indirim — bizi tekrar deneyin lütfen."))),
        Dialogue("sit-wa-order", "طلب كامل عبر واتساب (إندونيسيا)", "زبونة دائمة تراسلك على واتساب طالبة فستانين. الرسائل كما تجري فعلًا (اكتبها كما هي!).", Cefr.A1, listOf(DialogueTurn("C", "مرحبًا! الفستان الأزرق من أسبوع ما زال موجودًا؟", "Halo kak! Dress biru yang minggu lalu masih ada?", "Merhaba! Geçen haftaki mavi elbise hâlâ duruyor mu?"),DialogueTurn("S", "أهلًا بأختنا! موجود — مقاس M وL. أرسل لك صوره الآن.", "Wah kak langganan! Masih ada, ukuran M sama L. Fotonya saya kirim sekarang ya.", "Hoş geldin! Hâlâ var, M ve L beden. Fotoğrafı şimdi atıyorum."),DialogueTurn("C", "أريد اثنين: L أزرق وM أسود. السعر مع التوصيل؟", "Mau dua kak: L biru sama M hitam. Harga plus ongkir berapa?", "İki istiyorum: L mavi, M siyah. Kargo dahil kaç olur?"),DialogueTurn("S", "الاثنان 400 ألفًا + توصيل 20. مجموع 420. أرسل لك صور الألوان للتأكيد.", "Dua-duanya empat ratus, ongkir dua puluh. Total empat ratus dua puluh. Warna saya kirim dulu ya biar jelas.", "İkisi dört yüz, kargo yirmi; toplam dört yüz yirmi. Renk fotoğraflarını atayım, net olsun."),DialogueTurn("C", "تمام. عنواني: شارع النخيل 12، منزل أهلي: سارة.", "Oke kak. Alamat: Jalan Palma dua belas, rumah Sarah.", "Tamam. Adres: Palma sokak 12, Sarah."),DialogueTurn("S", "دوّنت: فستانان، Jalan Palma 12، سارة. صحيح؟ الدفع عبر:", "Saya catat: dua dress, Jalan Palma 12, Sarah. Sudah benar? Pembayaran ke BCA 123456789 a.n. Toko Rizki.", "Not aldım: iki elbise, Palma 12, Sarah. Doğru mu? Ödeme: IBAN TR12 3456 …"),DialogueTurn("C", "صحيح! حوّلت 420. هذه صورة الإيصال.", "Sudah benar kak! Sudah transfer empat ratus dua puluh. Ini buktinya.", "Doğru! Havaleyi yaptım, dekont burada."),DialogueTurn("S", "وصل الدفع، شكرًا! يُشحن غدًا صباحًا وسيصل بإذن الله بعد غد. رقم التتبع أرسله لك.", "Pembayaran masuk, makasih kak! Besok pagi saya kirim, kira-kira lusa sampai. Nomor resi nanti saya kirim.", "Ödeme geldi, teşekkürler! Yarın sabah kargoda, ertesi gün elinizde olur. Takip numarasını atarım."),DialogueTurn("C", "ممتاز، بانتظارك! شكرًا", "Sip kak, ditunggu ya! Makasih", "Harika, bekliyorum. Teşekkürler!"),DialogueTurn("S", "على الرحب! (بعد يومين) وصل الطلب؟ نتمنى أنه أعجبك 🌸", "Dengan senang hati! (2 hari kemudian) Paketnya sudah sampai kak? Semoga suka ya", "Rica ederim! (2 gün sonra) Paket ulaştı mı? Beğenmenizi umarım"))),
        Dialogue("dly-resto", "في مطعم شعبي (إندونيسيا)", "جلست في «warung» (مطعم صغير). النادل (mas) يستقبلك. جوعان بعد يوم طويل.", Cefr.A1, listOf(DialogueTurn("S", "تفضل! ماذا تأكل؟", "Silakan mas! Mau makan apa?", "Buyurun! Ne yemek istersiniz?"),DialogueTurn("C", "ما هو موجود اليوم؟", "Hari ini ada apa?", "Bugün ne var?"),DialogueTurn("S", "أرز مقلي بالدجاج، وشوربة، ومكرونة غورينغ.", "Ada nasi goreng ayam, sayur asem, sama mie goreng.", "Pilav, tavuk çorbası, makarna var."),DialogueTurn("C", "أرز مقلي واحد. لكن غير حار أرجوك!", "Nasi goreng satu. Tapi jangan pedas ya mas!", "Pilav olsun. Ama acı olmasın lütfen!"),DialogueTurn("S", "تمام! تشرب؟", "Oke! Minum apa?", "Tamam! Ne içersiniz?"),DialogueTurn("C", "شاي بارد واحد وبعيد ذلك لا شيء.", "Teh es satu aja.", "Bir buzlu çay yeter."),DialogueTurn("C", "(بعد الأكل) لذيذ جدًا! الحساب من فضلك.", "Enak banget! Bayar dong mas.", "Çok lezzetliydi! Hesap lütfen."),DialogueTurn("S", "18 ألفًا فقط. أكلت شهيًا!", "Delapan belas ribu mas. Makasih ya!", "On sekiz lira. Afiyet olsun!"))),
        Dialogue("dly-taxi", "تاكسي/مواصلات في تركيا", "أنت في تاكسي بإسطنبول. السائق (abi) سريع اللسان. تريد الوصول لحي كريم أو_baseline (تخيل: مول جواهر).", Cefr.A1, listOf(DialogueTurn("C", "مرحبًا! إلى هذا العنوان من فضلك.", "Halo! Ke alamat ini ya pak.", "Merhaba! Bu adrese lütfen."),DialogueTurn("S", "حسنًا سيدّي. سأستخدم العداد (taksimetre).", "Siap pak, saya pakai argo.", "Tamamdır beyefendi. Taksimetreyi açıyorum."),DialogueTurn("C", "كم يستغرق تقريبًا؟ أنا مستعقل قليلًا.", "Kira-kira berapa lama? Saya agak buru-buru.", "Ne kadar sürer? Biraz acelem var."),DialogueTurn("S", "بعون الله 20 دقيقة. حركة السير خفيفة اليوم.", "Insya Allah dua puluh menit. Macetnya lumayan ringan.", "İnşallah yirmi dakika. Trafik hafif bugün."),DialogueTurn("C", "ممتاز. هنا يمين عند الإشارة من فضلك.", "Bagus. Di lampu merah belok kanan ya pak.", "Harika. İşte burada sağa dönün lütfen, ışıkta."),DialogueTurn("S", "يمينًا… هذا المبنى الأصفر؟", "Kanan ya… yang gedung kuning ini?", "Sağ mı… bu sarı bina mı?"),DialogueTurn("C", "نعم بالضبط. توقف هنا رجاءً. كم المبلغ؟", "Iya betul. Berhenti di sini ya. Berapa totalnya?", "Evet aynen. Burada durun lütfen. Kaç oldu?"),DialogueTurn("S", "145 ليرة. أتعامل معك بصدق.", "Seratus empat puluh lima ribu.", "Yüz kırk beş lira oldu."),DialogueTurn("C", "خذ. زدك للجهد — أعطاك الله الصحة!", "Ini pak. Kembaliannya simpan aja, terima kasih!", "Buyurun. Üstü kalsın, kolay gelsin!"))),
        Dialogue("dly-pharmacy", "في الصيدلية (إندونيسيا)", "تشعر بصداع وألم حلق منذ يومين. دخلت أقرب apotek.", Cefr.A1, listOf(DialogueTurn("C", "مساء الخير. رأسي يؤلمني منذ أمس، وحلقي قليلًا.", "Selamat malam. Kepala saya sakit dari kemarin, tenggorokan agak perih.", "İyi akşamlar. Dünden beri başım ağrıyor, boğazım biraz yanıyor."),DialogueTurn("S", "هل معك حرارة؟ قِستها؟", "Demam nggak? Sudah diukur?", "Ateşiniz var mı, ölçtünüz mü?"),DialogueTurn("C", "أمس 38 درجة. اليوم لم أقس.", "Kemarin tiga puluh delapan. Hari ini belum diukur.", "Dün otuz sekizdi, bugün ölçmedim."),DialogueTurn("S", "هذه حبوب للصدأ، وهذا غرغرة للحلق. حار أم لا الحار؟", "Ini obat demam, ini obat kumur buat tenggorokan. Mau yang kerasa dingin?", "Bunlar ateş için, bu gargara boğaz için."),DialogueTurn("C", "طيب. كيف أشربها؟", "Baik. Gimana minumnya?", "Peki, nasıl kullanacağım?"),DialogueTurn("S", "حبة كل ثماني ساعات بعد الأكل. الغرغرة مرتين يوميًا.", "Satu tablet tiap delapan jam, sesudah makan. Kumurnya dua kali sehari.", "Sekiz saatte bir, yemekten sonra. Gargarayı günde iki kez."),DialogueTurn("C", "فهمت. كم المجموع؟", "Siap. Semuanya berapa?", "Anladım, hepsi kaç lira?"),DialogueTurn("S", "25 ألفًا فقط. أسرع بالشفاء! (الله يشفيك)", "Dua puluh lima ribu aja. Cepat sembuh ya!", "Yirmi beş lira. Geçmiş olsun!"))),
        Dialogue("dly-directions", "السؤال عن الطريق (إندونيسيا)", "تسير في حي جاكرتا تبحث عن محل قماش أخبرك عنه صديق. سألت شخصًا ودودًا عند البقالة.", Cefr.A1, listOf(DialogueTurn("C", "عفوًا، أين شارع مانديران من هنا؟", "Permisi, Jalan Mandiran di mana ya?", "Afedersiniz, Mandiran sokağı nerede?"),DialogueTurn("S", "مانديران؟ قريب. مستقيم حتى الإشارة.", "Mandiran? Dekat kok. Lurus sampai lampu merah.", "Mandiran mı? Yakın. Işığa kadar dosdoğru gidin."),DialogueTurn("C", "حسنًا، ثم؟", "Terus?", "Sonra?"),DialogueTurn("S", "عند الإشارة يسارًا، بعدها ستAVE المسجد مباشرة.", "Di lampu merah belok kiri, habis itu masjidnya langsung kelihatan.", "Işıkta sola dönün, hemen camiyi göreceksiniz."),DialogueTurn("C", "يسارًا عند الإشارة ثم المسجد… والمحل؟", "Belok kiri, terus masjid… tokonya di mana?", "Cami tamam, peki dükkân?"),DialogueTurn("S", "المحل قبالة المسجد تمامًا، لونه أخضر. إن وصلت للسوق الصغير فقد تجاوزته.", "Tokonya seberang masjid, warnanya hijau. Kalau sampai pasar kecil, sudah kelewat.", "Caminin karşısı, yeşil bina. Küçük pazara varsanız geçmişsiniz."),DialogueTurn("C", "فهمت تمامًا! هل أستطيع مشيًا؟", "Siap! Jalan kaki bisa?", "Anladım! Yürüyerek olur mu?"),DialogueTurn("S", "خمس دقائق مشيًا فقط. بالتوفيق!", "Lima menit jalan kaki aja. Semoga ketemu!", "Beş dakika yürürsünüz. Kolay gelsin!"))),
        Dialogue("dly-meet", "تعارف ودعوة شاي (تركيا)", "جارك التركي الجديد (abi) دعاك لشاي في محله الصغير. أول لقاء حقيقي.", Cefr.A1, listOf(DialogueTurn("S", "أهلًا جارنا! تفضل، الشاي على النار.", "Selamat datang tetangga! Silakan, tehnya lagi dibikin.", "Hoş geldin komşu! Buyur, çay demleniyor."),DialogueTurn("C", "أجل معروف — لأول مرة أدخل محلك.", "Terima kasih! Pertama kali saya ke sini.", "Hoş bulduk! İlk defa geliyorum dükkânına."),DialogueTurn("S", "من أين أنت يا ابن الحلال؟", "Kakak dari mana?", "Nerelisin gözüm?"),DialogueTurn("C", "من اليمن. أعيش هنا منذ سنة، وأتعلم التركية.", "Saya dari Yaman. Setahun di sini, lagi belajar bahasa.", "Yemenliyim. Bir yıldır buradayım, Türkçe öğreniyorum."),DialogueTurn("S", "ما شاء الله! تركيتك أحسن من ناس هنا! (يضحك). البيت أم العمل؟", "Subhanallah! Bahasanya enak! Udah kerja atau?", "Maşallah! Türkçen bizden iyi neredeyse! Ev mi, iş mi?"),DialogueTurn("C", "عندي محل صغير للبضائع المنزلية. محلك هذا جميل ورثته عن أبيك؟", "Saya ada toko kecil barang rumah tangga. Ini warisan bapak?", "Küçük bir dükkânım var, ev eşyası. Burası güzelmiş — babandan mı kaldı?"),DialogueTurn("S", "أبي وأبي أبي — 40 سنة. اشرب، حدثني عن اليمن… (يصب الشاي)", "Dari bapak saya, dari kakek. Empat puluh tahun. Minum dulu, cerita tentang Yaman…", "Babamdan, ondan da babasından — kırk yıldır. İç bakalım, Yemen'i anlat…"),DialogueTurn("C", "بالتأكيد. صديقك أنا من اليوم — ليكن عملنا كله بركة.", "Tentu. Mulai hari ini kita teman. Semoga rezeki kita berkah.", "Elbette. Bugünden arkadaşımsın — işimiz bereketli olsun."))),
        Dialogue("dly-phone", "مكالمة هاتفية (تركية)", "يتصل بك رقم تركي — زبون محتمل سمع عن محلك. المكالمات أصعب من الحوار المباشر (بلا وجوه وإيماءات) — إليك النموذج.", Cefr.A1, listOf(DialogueTurn("C", "ألو؟ مساء الخير، معك مراد. هذا محل الأدوات المنزلية؟", "Halo? Selamat malam, saya Murat. Ini toko perkakas rumah?", "Alo? İyi akşamlar, Murat ben. Ev eşyası dükkânı mı burası?"),DialogueTurn("S", "ألو، نعم بالضبط! معك أحمد، تفضل كيف أساعدك؟", "Halo, iya betul! Saya Ahmed. Ada yang bisa saya bantu?", "Alo, evet aynen! Ahmed ben, buyurun nasıl yardımcı olabilirim?"),DialogueTurn("C", "سمعت عندكم غسالات صغيرة. كم سعرها تقريبًا؟", "Katanya ada mesin cuci kecil. Harganya kira-kira berapa?", "Duydum ki küçük çamaşır makineleriniz var. Fiyatları ne civarı?"),DialogueTurn("S", "نعم عندنا. تبدأ من 4500 ليرة. متى تحتاجها؟", "Ada. Mulai dari empat ribu lima ratus. Kapan butuhnya?", "Evet var. Dört bin beş yüzden başlıyor. Ne zaman lazım?"),DialogueTurn("C", "عندي وقت غدًا. أين موقعكم بالضبط؟", "Besok saya bisa. Alamatnya di mana persisnya?", "Yarın vaktim var. Adresiniz tam olarak nerede?"),DialogueTurn("S", "شارع الجمهورية رقم 12، مقابل الصيدلية الخضراء. أعمل حتى الثامنة مساء.", "Jalan Republik nomor 12, seberang apotek hijau. Buka sampai jam delapan malam.", "Cumhuriyet Caddesi 12, yeşil eczanenin karşısı. Akşam sekize kadar açığız."),DialogueTurn("C", "ممتاز. أحجز لي واحدة غسالة 5000 ليرة بلا صبغة؟", "Mantap. Bisa simpan satu yang lima ribu?", "Süper. Beş binlik bir tanesini ayırtır mısınız bana?"),DialogueTurn("S", "حجزتها باسمك! أرسل لي موقعك واتساب أرسل لك الخريطة.", "Sudah saya simpan atas nama! Chat WA ya, saya kirim lokasi.", "Ayırttım, adınıza! WhatsApp'tan yazın, haritayı atayım."),DialogueTurn("C", "شكرًا جزيلًا! غدًا عندك إن شاء الله.", "Makasih banyak! Besok ketemu ya insya Allah.", "Çok teşekkürler! Yarın görüşürüz inşallah."))),
        Dialogue("dly-hotel", "في فندق (تركيا)", "وصلت أونالان لمدينة عن عمل. في الاستقبال (respsiyon) موظفة ودودة.", Cefr.A1, listOf(DialogueTurn("C", "مساء الخير. حجزت غرفة باسمي: أحمد، لثلاث ليالٍ.", "Selamat malam. Ada reservasi atas nama saya: Ahmad, tiga malam.", "İyi akşamlar. Rezervasyonum var: Ahmed adına, üç gece."),DialogueTurn("S", "أهلًا بك أحمد بك. غرفة مفردة بإطلالة؟ جهزناها.", "Selamat datang Pak Ahmad. Kamar single dengan pemandangan sudah siap.", "Hoş geldiniz Ahmed Bey. Tek kişilik, manzaralı oda hazır."),DialogueTurn("C", "الإفطار من أي ساعة؟ وهل فيه خيارات حلال نباتية؟", "Sarapan dari jam berapa? Ada menu helal vegetarian?", "Kahvaltı saat kaçtan? Vejetaryen helal seçenek var mı?"),DialogueTurn("S", "من السابعة حتى العاشرة، بوفيه مفتوح وفيه كل الخيارات.", "Dari jam tujuh sampai sepuluh, prasmanan, semua pilihan ada.", "Yediden ona, açık büfe, her seçenek mevcut."),DialogueTurn("C", "ممتاز. الواي فاي كلمة السر؟", "Mantap. Password WiFi-nya apa?", "Süper. WiFi şifresi nedir?"),DialogueTurn("S", "على البطاقة: «misafir2026». الغرفة 305، المصعد يمينك.", "Ada di kartu: «misafir2026». Kamar 305, lift di kanan.", "Kartta yazıyor: «misafir2026». Oda 305, asansör sağınızda."),DialogueTurn("C", "شكرًا. الدفع الآن أم عند المغادرة؟", "Makasih. Bayar sekarang atau saat checkout?", "Teşekkürler. Ödeme şimdi mi, çıkışta mı?"),DialogueTurn("S", "كما تحب. إقامتك موفقة! أي شيء أنا بالخدمة.", "Terserah kakak. Selamat menginap! Kalau ada apa-apa, panggil saja.", "Nasıl isterseniz. İyi konaklamalar! Bir şey olursa emrinizdeyim."),DialogueTurn("C", "دعني الآن وأدفع عند المغادرة. أعطاك الله العافية.", "Saat checkout nanti saja. Terima kasih ya!", "Çıkışta vereyim o zaman. Kolay gelsin!"))),
        Dialogue("dly-smalltalk", "دردشة الجيران والصغائر (إندونيسيا)", "في إندونيسيا كل من تقابلها يسألك: «Mau ke mana?» (إلى أين؟). إنه ليس تحقيقًا — إنه تحية! إليك الرقصة الاجتماعية كاملة.", Cefr.A1, listOf(DialogueTurn("S", "أخي! إلى أين؟ (جارك من الشرفة)", "Kak! Mau ke mana?", "Nereye gidiyorsun kardeşim?"),DialogueTurn("C", "إلى السوق قليلًا. وأنت؟", "Ke pasar sebentar. Kakak sendiri?", "Pazara bir şey almaya. Sen nereye?"),DialogueTurn("S", "أنا جالس أرتب المحل. هل أكلت؟", "Saya nitip toko. Udah makan?", "Dükkândayım işte. Yemek yedin mi?"),DialogueTurn("C", "أكلت الحمد لله. والعمل كيف يدور؟", "Udah, alhamdulillah. Jualannya lancar?", "Yedim elhamdülillah. İşler nasıl?"),DialogueTurn("S", "بسط الحمد لله، الروبيات تجري هادئة. أطفالك بخير؟", "Alhamdulillah lancar aja. Anak-anak sehat?", "İyidir elhamdülillah. Çocuklar iyi mi?"),DialogueTurn("C", "بخير، بدأوا المدرسة. طيب أنا ماشي — سلملي على العائلة!", "Sehat, sekolah udah mulai. Ya udah saya duluan ya, salam bu keluarga!", "İyiler, okul başladı. Ben gideyim, aileye selam!"),DialogueTurn("S", "سلامي لهم! حافظ على نفسك يا أخي.", "Salam balik! Hati-hati ya kak!", "Selm olsun, kendine iyi bak!"))),
        Dialogue("dly-airport", "في المطار (إندونيسيا)", "أنت مسافر في مطار سوكارنو-هاتا بجاكرتا. تصل كاونتر التسجيل قبل رحلتك بساعتين.", Cefr.A1, listOf(DialogueTurn("S", "تفضل سيدي! جواز السفر والتذكرة رجاءً.", "Silakan Pak. Paspor sama tiketnya ya.", "Buyurun efendim, pasaport ve bilet lütfen."),DialogueTurn("C", "تفضل — حقيبة واحدة للتسجيل وحقيبة يد.", "Ini Pak. Satu bagasi check-in, satu bagasi kabin.", "Buyurun. Bir valiz kayıt için, bir el bagajı."),DialogueTurn("S", "حسنا. مقعد نافذة أم ممر؟", "Oke. Kursi dekat jendela atau dekat gang?", "Pencere mi koridor mu?"),DialogueTurn("C", "نافذة رجاءً. كم كيلو مسموح؟", "Dekat jendela ya. Bagasi boleh berapa kilo?", "Pencere lütfen. Bagaj limiti kaç kilo?"),DialogueTurn("S", "20 كيلو. حقيبتك 18 — تمام. البوابة 7، الصعود 10:20.", "Dua puluh kilo. Punya Bapak delapan belas — aman. Gate tujuh, boarding jam sepuluh dua puluh.", "Yirmi kilo. Sizinki on sekiz — sorun yok. Kapı 7, biniş 10.20."),DialogueTurn("C", "شكرًا! أين البوابة 7؟", "Makasih! Gate tujuh di mana ya?", "Teşekkürler! Yedi numaralı kapı nerede?"),DialogueTurn("S", "يمينًا بعد التفتيش، ثم انزل السلم. رحلة موفقة!", "Kanan setelah pemeriksaan, terus turun tangga. Selamat jalan Pak!", "Kontrolten sonra sağda, merdivenlerden inin. İyi uçuşlar!"))),
        Dialogue("dly-transport", "المواصلات العامة (باص/مترو تركيا)", "أول مرة تستخدم المترو بإسطنبول. تحتاج بطاقة (İstanbulkart) والوصول لحي شيشلي.", Cefr.A1, listOf(DialogueTurn("C", "عفوًا، أين أشتري بطاقة إسطنبول؟", "Permisi, İstanbulkart beli di mana?", "Afedersiniz, İstanbulkartı nereden alabilirim?"),DialogueTurn("S", "هناك آلة صفراء. تريد تشحنها؟", "Ada mesin kuning di situ. Mau top up?", "Şurada sarı cihaz var. Yükleme yapmak istiyor musunuz?"),DialogueTurn("C", "نعم، 50 ليرة. كيف أعرف متى أنزل؟", "Iya, lima puluh ribu. Berhentinya mana?", "Evet, elli lira. İnmem gereken durağı nasıl anlarım?"),DialogueTurn("S", "إلى شيشلي: ست محطات، اسمها مكتوب على الشاشة والجدران.", "Ke Şişli enam stasiun. Namanya ada di layar sama dinding.", "Şişli’ye altı durak. İsmi ekranda ve duvarlarda yazar."),DialogueTurn("C", "أشكرك — الباب يفتح تلقائيًا؟", "Makasih! Pintunya buka sendiri?", "Teşekkürler — kapılar otomatik mi açılıyor?"),DialogueTurn("S", "نعم، لكن أسرع — تُغلق سريعًا. «انتبه للأبواب!»", "Iya, tapi cepat ya, pintunya cepet nutup. Hati-hati!", "Evet ama hızlı olun, çabuk kapanır. «Kapılara dikkat!»"),DialogueTurn("C", "(عند الوصول) عفوًا، هذه شيشلي؟", "Permisi, ini Şişli?", "(inerken) Afedersiniz, burası Şişli mi?"),DialogueTurn("S", "بالضبط — المخرج الأيمن للخروج. مع السلامة!", "Betul! Keluar pintu kanan. Hati-hati ya!", "Aynen öyle — sağ çıkış. İyi günler!"))),
        Dialogue("dly-mall", "في المول التركي (محل + كاشير)", "في مول بإسطنبول تريد شراء سترة. الأسعار ثابتة (pazarlık yok في المولات) لكن الأقساط موجودة.", Cefr.A1, listOf(DialogueTurn("S", "أهلًا! تفضل، السترات الجديدة هناك.", "Selamat datang! Jaket baru di situ kak.", "Hoş geldiniz! Yeni ceketler şurada buyurun."),DialogueTurn("C", "كم هذه؟ معلى لافتة خصم؟", "Ini berapa? Lagi diskon?", "Bu kaç lira? İndirimde mi?"),DialogueTurn("S", "900 — خصم 30% من 1290. عرض هذا الأسبوع فقط.", "Sembilan ratus. Diskon tiga puluh persen, minggu ini aja.", "Dokuz yüz. Bin iki yüz doksandan yüzde otuz indirimli, sadece bu hafta."),DialogueTurn("C", "أقساط ممكنة؟", "Bisa cicilan?", "Taksit yapılıyor mu?"),DialogueTurn("S", "نعم — 9 أقساط بسعر النقدي مع بطاقات الشريك.", "Bisa! Sembilan cicilan tanpa bunga.", "Evet, anlaşmalı kartlarla peşin fiyatına dokuz taksit."),DialogueTurn("C", "أجرب مقاس L أولًا.", "Coba dulu ukuran L ya.", "Önce L bedenini deneyeyim."),DialogueTurn("S", "غرف القياس خلفك. إن لم يناسب، عندي XL أيضًا.", "Kamar pas di belakang. Kalau nggak muat, ada XL.", "Kabin arkanızda. Olmazsa XL de var."),DialogueTurn("C", "ممتاز — آخذها. الفيشت رجاءً للضمان.", "Oke, saya ambil. Struknya sekalian ya buat garansi.", "Süper, alıyorum. Garanti için fişini alayım."))),
        Dialogue("dly-super", "في السوبرماركت (إندونيسيا)", "في سوبرماركت كبير بجاكرتا (Superindo). تبحث عن أرز وأدوات منزلية ثم تدفع.", Cefr.A1, listOf(DialogueTurn("C", "عفوًا، أين أجد الأرز والمكرونة؟", "Permisi, beras sama mie di mana ya?", "Affedersiniz, pirinç ve makarna nerede?"),DialogueTurn("S", "الممر 3 للأرز، والمكرونة ممر 4 بجانبه.", "Beras di lorong tiga, mie di lorong empat sebelahnya.", "Pirinç üçüncü koridorda, makarna yanındaki dördüncüde."),DialogueTurn("C", "وهذه المكانس؟ أرى لافتة خصم.", "Terus sapu ini? Ada tulisan diskon.", "Süpürge şurada mı? İndirim etiketi görüyorum."),DialogueTurn("S", "نعم — اشترِ واحدة والثانية بنصف السعر. العرض ينتهي غدًا.", "Iya, beli satu dapat yang kedua setengah harga. Promo habis besok.", "Evet, bir alana ikincisi yarı fiyat. Kampanya yarın bitiyor."),DialogueTurn("C", "أخذ اثنتين إذن. الكاشير أين؟", "Ambil dua deh. Kasirnya di mana?", "İki alayım o zaman. Kasa nerede?"),DialogueTurn("S", "أمامك مباشرة — الصناديق الثلاثة المفتوحة.", "Dekpan Bapak, kasir yang tiga terbuka.", "Hemen önünüzde, açık üç kasa var."),DialogueTurn("S", "(عند الكاشير) عضوية معك؟ حقيبة أم كيس؟", "(di kasir) Ada kartu member? Mau bawa tas sendiri atau kantong?", "(kasada) Kartınız var mı? Poşet ister misiniz?"),DialogueTurn("C", "بدون عضوية، ومعي حقيبة. بطاقة QRIS.", "Nggak ada member. Bawa tas sendiri. Bayar QRIS ya.", "Kart yok, kendi çantam var. Kartla ödeyeyim."))),
        Dialogue("dly-cafe", "في المقهى (قهوة تركية)", "مقهى شعبي (kıraathane) بحي إسطنبولي. ترید تجربة القهوة التركية الأصيلة.", Cefr.A1, listOf(DialogueTurn("S", "أهلًا! ماذا تشرب؟", "Selamat datang! Mau minum apa?", "Hoş geldin! Ne içersin?"),DialogueTurn("C", "قهوة تركية — لكن كم سكر أضع؟ ماذا تنصح؟", "Kopi Turki. Gulanya berapa? Saran kakak apa?", "Türk kahvesi ama şekeri nasıl? Ne önerirsin?"),DialogueTurn("S", "الأولى لك: «orta» — سكر متوسط. سادة للخبراء!", "", "İlk denemen için «orta» — orta şekerli. Sade ustalara kalır!"),DialogueTurn("C", "إذن orta. ومعها طياب؟", "Oke. Sama camilan apa?", "Öyle olsun. Yanına bir şey alsam?"),DialogueTurn("S", "لقمة (lokma) أو حلاوة طحينية مع القهوة دائمًا.", "Cemilan manis cocok sama kopi.", "Lokma ya da tahin helvası iyi gider."),DialogueTurn("C", "لقمة إذن. (بعد الشرب) ممتازة! كيف أعرف نهايتها؟", "Bagus banget! Kopinya sampai mana boleh diminum?", "Lokma olsun. (içtikten sonra) Harika! Tabakta nerede bittiğini nasıl anlarım?"),DialogueTurn("S", "اشرب حتى تصل للثقل — التفل يبقى. وعليك قراءة فنجانك!", "", "Ağırlaşana kadar iç — telvenin üstü kalır. Bir de fincanını okut!"),DialogueTurn("C", "هههه لاحقًا! الحساب رجاءً.", "Nanti aja hehe. Bonnya ya.", "Haha, sonra belki! Hesap lütfen."))),
        Dialogue("dly-bank", "في البنك (إندونيسيا)", "تريد فتح حساب بنكي بجاكرتا لتحويلات عملك. الموظفة تتحدث الإنجليزية المبسطة والإندونيسية.", Cefr.A1, listOf(DialogueTurn("C", "صباح الخير. أريد فتح حساب توفير.", "Selamat pagi. Saya mau buka rekening tabungan.", "Günaydın. Bir tasarruf hesabı açmak istiyorum."),DialogueTurn("S", "أهلًا. معك جواز وKITAS/إقامة؟ وصورة شخصية.", "Selamat datang. Paspor sama KITAS ada? Foto ukuran paspor juga.", "Hoş geldiniz. Pasaport ve ikamet izni var mı? Bir de fotoğraf."),DialogueTurn("C", "معي كل شيء. هل هناك حد أدنى للإيداع؟", "Semua ada. Minimal setoran berapa?", "Hepsi var. Minimum yatırım tutarı ne kadar?"),DialogueTurn("S", "100 ألف روبية. وسنفعّل التطبيق والـm-banking فورًا.", "Seratus ribu. Nanti aplikasi sama m-banking langsung aktif.", "Yüz bin. Uygulama ve mobil bankaçılık hemen aktif olur."),DialogueTurn("C", "ممتاز. وأريد تحويلًا شهريًا آليًا لمورد — الرسوم كم؟", "Bagus. Saya mau transfer otomatis tiap bulan ke supplier. Biayanya berapa?", "Harika. Her ay otomatik havale istiyorum. Ücreti ne kadar?"),DialogueTurn("S", "التحويل المحلي 6.500 بين بنوك نفس الشبكة مجانًا.", "Transfer antar bank enam ribu lima ratus, sesama bank gratis.", "Bankalar arası küçük bir ücret, aynı banka ücretsiz."),DialogueTurn("C", "واضح. وقّع هنا؟ شكرًا جزيلًا!", "Jelas. Tanda tangan di sini? Makasih banyak ya!", "Anlaşıldı. Buraya imza atıyorum? Çok teşekkürler!"),DialogueTurn("S", "هنا وهنا. بطاقتك بعد أسبوع، والرقم السري عبر الرسالة. دائمًا في خدمتك!", "Di sini sama di sini. Kartunya minggu depan, PIN dikirim lewat SMS. Terima kasih!", "Buradan ve buradan. Kartınız bir hafta sonra, şifre SMS ile. İyi günler!"))),
        Dialogue("dly-clinic", "في العيادة/المستشفى (إندونيسيا)", "ألم في الحلق وحمى منذ يومين. ذهبت لعيادة قريبة (klinik) بجوار منزلك.", Cefr.A1, listOf(DialogueTurn("C", "أريد الكشف — حلقي يؤلمني وحمى منذ أمس.", "Mau periksa. Tenggorokan sakit, demam dari kemarin.", "Muayene olmak istiyorum. Boğazım ağrıyor, dünden beri ateşim var."),DialogueTurn("S", "هل هذا أول زيارة؟ سجل بياناتك هنا.", "Kunjungan pertama ya? Isi data dulu sini.", "İlk kez mi geliyorsunuz? Bilgilerinizi buraya yazın."),DialogueTurn("C", "تم. كم الانتظار؟ أستطيع الدفع بالبطاقة؟", "Sudah. Antri lama? Bayar pakai kartu bisa?", "Oldu. Bekleme ne kadar? Kartla ödeyebilir miyim?"),DialogueTurn("S", "طبيب واحد قبلك — 15 دقيقة. نقدي أو QRIS فقط.", "Satu lagi sebelum Bapak, lima belas menit. Tunai atau QRIS aja.", "Bir kişi önünüzde, on beş dakika. Nakit ya da kart."),DialogueTurn("S", "(الطبيب) قل «آه»… احمرار خفيف. أنفلونزا موسمية.", "(dokter) Bilang “aaah”… merah sedikit. Ini flu biasa.", "(doktor) “Aaa” deyin… hafif kızarıklık. Mevsimsel grip."),DialogueTurn("C", "أحتاج مضادًا حيويًا؟", "Perlu antibiotik?", "Antibiyotik gerekir mi?"),DialogueTurn("S", "لا — فيروس. خافض حرارة وغرغرة وراحة 3 أيام.", "Tidak, ini virus. Obat demam, kumur, istirahat tiga hari.", "Hayır, virüs. Ateş düşürücü, gargara ve üç gün dinlenin."),DialogueTurn("C", "شكرًا يا دكتور. أكتب لي هذا لجهة عملي؟", "Makasih Dok. Bisa dibuatkan surat sakit buat kantor?", "Teşekkürler doktor. İşyerine rapor yazabilir misiniz?"))),
        Dialogue("dly-embassy", "في السفارة (تركيا)", "في سفارة بأنقرة لتقديم طلب (تأشيرة/تصديق أوراق). الموظف يتحدث بتركية رسمية هادئة.", Cefr.A1, listOf(DialogueTurn("S", "صباح الخير. رقم موعدك؟", "Selamat pagi. Nomor antrian appointment?", "Günaydın. Randevu numaranız?"),DialogueTurn("C", "صباح النور — 204. هذا ملفي كاملًا.", "Nomor dua ratus empat. Berkas saya lengkap.", "Günaydın, iki yüz dört. Dosyam eksiksiz burada."),DialogueTurn("S", "جواز، صور، كشف حساب، دعوة. ينقص شهادة عمل.", "Paspor, foto, rekening koran, surat undangan. Kurang surat kerja.", "Pasaport, foto, banka dökümü, davetiye. Eksik olan iş belgesi."),DialogueTurn("C", "أحضرتها! معها ترجمة موثقة — تكفي؟", "Saya bawa! Sama terjemahan tersumpah — cukup?", "Getirdim! Yeminli tercümesi de var — yeterli mi?"),DialogueTurn("S", "تكفي. الرسوم تُدفع عند الشباك 3. المدة 15 يوم عمل.", "Cukup. Biayanya di loket tiga. Prosesnya lima belas hari kerja.", "Yeterli. Harç üç numaralı gişede. Süre on beş iş günü."),DialogueTurn("C", "كيف أتابع الطلب؟ برسالة؟", "Gimana cara lacak permohonan? Lewat SMS?", "Başvuruyu nasıl takip ederim? SMS ile mi?"),DialogueTurn("S", "برسالة للرقم المسجل، أو موقعنا برقم الجواز.", "Lewat SMS ke nomor terdaftar, atau cek di situs pakai nomor paspor.", "Kayıtlı numaraya SMS, ya da siteden pasaport numarasıyla."),DialogueTurn("C", "ممتاز. يومًا سعيدًا، وشكرًا على صبرك.", "Siap. Sukses ya, makasih sabarnya.", "Harika. İyi günler, sabrınız için teşekkürler."))),
        Dialogue("dly-police", "في مركز الشرطة (تركيا)", "سرق هاتفك في المواصلات. تذهب لأقرب مركز (karakol) لتقديم بلاغ تحتاجه للتأمين والخط الجديد.", Cefr.A1, listOf(DialogueTurn("C", "مساء الخير. أريد تقديم بلاغ — سُرق هاتفي في المترو.", "Selamat malam. Saya mau laporan — HP saya dicuri di kereta.", "İyi akşamlar. Tutnak istiyorum — metroda telefonum çalındı."),DialogueTurn("S", "متى وأين بالضبط؟ أي خط؟", "Kapan dan di stasiun mana? Kartunya operator apa?", "Ne zaman, hangi durakta? Hattı hangi operatör?"),DialogueTurn("C", "حوالي السادسة، محطة تقسيم. رقمي ومحفظتي به.", "Jam enam-an, stasiun Taksim. Nomor saya sama dompet di dalam.", "Saat altı sularında, Taksim durağı. Numaram ve cüzdanım içindeydi."),DialogueTurn("S", "حسنًا. هويتك وجوازك. نحرر بلاغًا رقميًا الآن.", "Oke. KTP sama paspor. Sekarang kami buat laporan resmi.", "Pekâlâ. Kimlik ve pasaportunuz. Şimdi tutanak tutuyoruz."),DialogueTurn("C", "هل أستطيع نسخة للتأمين وشركة الاتصال؟", "Bisa dapat salinan buat asuransi sama operator?", "Sigorta ve operatör için bir kopya alabilir miyim?"),DialogueTurn("S", "نعم — نسختان مختومتان. واعرضها للخط الجديد لتحتفظ برقمك.", "Bisa, dua lembar cap. Buat kartu baru, nomor lama bisa dipindah.", "Evet, iki mühürlü kopya. Yeni hatta numaranızı taşıyabilirsiniz."),DialogueTurn("C", "شكرًا لاهتمامكم. هل هناك نصيحة؟", "Makasih perhatiannya. Ada saran?", "İlginiz için teşekkürler. Bir tavsiyeniz var mı?"),DialogueTurn("S", "المتاجر المزدحمة ونهاية العربات — انتبه، وسجل الهاتف في تطبيق (IMEI).", "Tempat ramai sama ujung gerbong — hati-hati, catat IMEI-nya.", "Kalabalık yerler ve vagon sonları — dikkat edin, IMEI’yi kayıt edin."))),
        Dialogue("dly-job", "مقابلة عمل (تركيا)", "مقابلة لبائع/أمين مخزن في شركة تجارية بإسطنبول. مدير الموارد البشرية ودود لكنه محترف.", Cefr.A1, listOf(DialogueTurn("S", "أهلًا. تعرّف بنفسك باختصار.", "Silakan. Ceritakan singkat tentang diri Bapak.", "Hoş geldiniz. Kendinizden kısaca bahsedin."),DialogueTurn("C", "أحمد، من اليمن. 3 سنوات خبرة مبيعات بالتجزئة، أتحدث العربية والإنجليزية وأتعلم التركية بسرعة.", "Ahmad, dari Yaman. Tiga tahun pengalaman jualan eceran, bisa Arab sama Inggris, lagi cepat belajar bahasa Turki.", "Ahmed, Yemenliyim. Perakende satışta üç yıl tecrübem var; Arapça ve İngilizce biliyorum, Türkçeyi hızlı öğreniyorum."),DialogueTurn("S", "لماذا شركتنا تحديدًا؟", "Kenapa milih tempat kami?", "Neden özellikle bizim firmamız?"),DialogueTurn("C", "تعملون بالجملة مع الشرق الأوسط — لغتي وشبكة علاقاتي تخدم هذا الخط مباشرة.", "Kalian main grosir ke Timur Tengah — bahasa sama relasi saya langsung kepake di lini itu.", "Orta Doğu ile toptan çalışıyorsunuz — dilim ve ilişkilerim bu hatta doğrudan hizmet eder."),DialogueTurn("S", "نقاط قوتك وضعفك؟", "Kekuatan sama kelemahan Bapak apa?", "Güçlü ve zayıf yönleriniz?"),DialogueTurn("C", "قوتي: التفاوض وبناء الثقة مع الزبون. وضعفي: تركيتي بعد — أصلحه بدروس مسائية ثلاث مرات أسبوعيًا.", "Kekuatan: negosiasi sama bangun kepercayaan. Kelemahan: bahasa Turki belum lancar — saya perbaiki les malam.", "Gücüm: pazarlık ve müşteriyle güven kurmak. Zayıfım: Türkçem henüz — akşam kurslarıyla üç günde bir düzeltiyorum."),DialogueTurn("S", "صادق وأحببته. الراتب المتوقع؟", "Jujur, saya suka. Gaji yang diharapkan?", "Dürüst sevdim. Beklenen maaşınız?"),DialogueTurn("C", "بحسب سوق إسطنبول: بين X وY — وأقدّر أن أبدأ أدنى قليلًا مع مراجعة بعد 3 أشهر إثباتًا.", "Standar Istanbul antara X dan Y — boleh mulai dikit di bawah, review lagi tiga bulan.", "İstanbul piyasasına göre X ile Y arası — kanıtlayınca üç ay sonra gözden geçirilmek üzere biraz altından başlayabilirim."),DialogueTurn("S", "اتفاقنا مبدئيًا. سننتظر مكالمتنا خلال الأسبوع.", "Deal awal. Minggu ini kami kabari lagi ya.", "Prensipte anlaştık. Bu hafta içinde döneriz."))),
        Dialogue("dly-campus", "في الجامعة (إندونيسيا)", "طالب دولي في حرم جامعي بجاكرتا. تسأل موظف الإدارة عن تسجيل الفصل ومصادر التعلم.", Cefr.A1, listOf(DialogueTurn("C", "عفوًا، متى يفتح تسجيل الفصل القادم؟", "Permisi, pendaftaran semester depan kapan dibuka?", "Affedersiniz, gelecek dönemin kayıtları ne zaman açılıyor?"),DialogueTurn("S", "الأسبوع القادم عبر النظام — من الاثنين حتى الجمعة.", "Minggu depan lewat sistem, dari Senin sampai Jumat.", "Gelecek hafta online, pazartesiden cumaya kadar."),DialogueTurn("C", "والمكتبة؟ هل تتاح للطلاب الدوليين مساءً؟", "Terus perpustakaan? Mahasiswa internasional bisa masuk malam?", "Kütüphane nasıl? Uluslararası öğrenciler akşam girebiliyor mu?"),DialogueTurn("S", "حتى التاسعة — بطاقتك الجامعية تفتح البوابات.", "Sampai jam sembilan malam. Kartu mahasiswanya bisa buka pintu.", "Dokuz akşama kadar. Öğrenci kartınız kapıları açıyor."),DialogueTurn("C", "هل توجد مجموعات دراسة لمادة الإحصاء؟", "Ada kelompok belajar buat statistik nggak?", "İstatistik için çalışma grubu var mı?"),DialogueTurn("S", "اسأل مكتب الطلاب (BEM) — ينظمونها كل فصل. وسيجد زملاءك بلا عناء.", "Tanya aja ke BEM. Mereka bikin tiap semester, gampang nemu teman.", "Öğrenci ofisine sorun — her dönem düzenliyorlar, arkadaş bulmak kolay."),DialogueTurn("C", "أخيرًا: أنصحني بشيء واحد لنجاحي هنا؟", "Terakhir, satu saran biar sukses di sini?", "Son olarak, burada başarılı olmak için bir tavsiye?"),DialogueTurn("S", "السؤال لا ينقص طالبًا — اسأل محاضريك وزملاءك، والشبكة هنا كل شيء.", "Bertanya tidak bikin bodoh. Tanya dosen sama teman-teman — di sini jaringan itu segalanya.", "Sormak öğrenciyi küçültmez — hocalarınıza ve arkadaşlarınıza sorun; burada network her şeydir."))),
        Dialogue("dly-apartment", "إيجار شقة (تركيا)", "تريد استئجار شقة صغيرة بحي عائلي بإسطنبول. المعلم (صاحب الشقة) يعرضها عليك.", Cefr.A1, listOf(DialogueTurn("S", "تفضل، الشقة طابق ثالث، جنوبية الإطلالة.", "Silakan, lantai tiga, arah selatan.", "Buyurun, üçüncü kat, cephe güney."),DialogueTurn("C", "جميلة. السخان والمطبخ؟ والفاتورة الشهرية تقريبًا؟", "Bagus. Pemanas sama dapur? Iuran bulanan kira-kira berapa?", "Güzel. Kombi ve mutfak? Aidat ve faturalar ne civarı?"),DialogueTurn("S", "سخان طبيعي، مطبخ مجهز. الديعة شهران، والإيجار شهريًا 15 ألفًا.", "Pemanas gas, dapur lengkap. Deposit dua bulan, sewa lima belas juta.", "Doğalgaz kombi, eşyalı mutfak. Depozito iki kira, aylık on beş bin."),DialogueTurn("C", "ممكن خصمًا لتعاقد سنتين؟ أنا مستقر عملًا.", "Kalau kontrak dua tahun bisa turun? Kerja saya tetap.", "İki yıllık sözleşmeye indirim olur mu? İşim stabil."),DialogueTurn("S", "ل سنتين: 14.5 والصيانة البسيطة عليّ.", "Kalau dua tahun jadi empat belas setengah, perbaikan kecil saya tanggung.", "İki yıla: on dört bin beş yüz, küçük bakımlar benden."),DialogueTurn("C", "جيد. أشترط بالعقد: فاتورة كاملة شهريًا وجرد عدّات موثق.", "Oke. Di kontrak dicatat: struk rutin sama inventaris lengkap.", "Makul. Sözleşmeye not düşelim: düzenli fatura ve sayımlı envanter."),DialogueTurn("S", "عادل. أحضر مترجمًا للعقد أو أنسخه لك عربيًا.", "Adil. Bawa penerjemah buat kontrak, atau saya kasih salinan bahasa Arab.", "Adil. Sözleşmeye tercüman getirin ya da size Arapça kopyasını vereyim."),DialogueTurn("C", "متفقون! أول الشهر القادم التسليم. كتبتَ بركة!", "Deal! Awal bulan depan serah terima. Semoga berkah ya Pak!", "Anlaştık! Gelecek ay başında teslim. Hayırlı olsun bize!"))),
        Dialogue("dly-carrental", "تأجير سيارة (إندونيسيا)", "تريد استئجار سيارة ليومين لجولة عمل خارج جاكرتا. المكتب صغير والأسعار تتفاوض.", Cefr.A1, listOf(DialogueTurn("C", "كم يوميًا لسيارة أوتوماتيك؟ وبأي شروط؟", "Per hari berapa untuk yang matic? Syaratnya gimana?", "Otomatik günlüğü kaç? Şartlar nasıl?"),DialogueTurn("S", "350 ألفًا اليومي، بنزين عليك. رخصة وجواز فقط.", "Tiga ratus lima puluh per hari, bensin di luar. SIM sama paspor aja.", "Günlük üç yüz elli, benzin hariç. Sadece ehliyet ve pasaport."),DialogueTurn("C", "أفحص السيارة أولًا — أصدّق الخدوش بعدو معك.", "Boleh cek dulu? Luka sama baretnya saya foto bareng kakak.", "Aracı kontrol edeyim — çizikleri sizinle fotoğraflayayım."),DialogueTurn("S", "عين ملاحظة! خذ وقتك — الشفافية راحتك.", "Wah bagus, teliti! Santai aja, transparan itu enak.", "Dikkatiniz güzel! Acele etmeyin, şeffaflık konfor demektir."),DialogueTurn("C", "والتأمين؟ إن وقع حادث ماذا أشمل؟", "Kalau kecelakaan gimana? Asuransinya cover apa aja?", "Kaza olursa? Sigorta neyi kapsıyor?"),DialogueTurn("S", "تأمين شامل بخصم 500 ألف عند الحادث. الصوارئ مجانية.", "Asuransi all risk, tapi kalau kejadian deductible lima ratus. Ban sama kaca sendiri.", "Kasko var, hasarda eks payı beş yüz bin. Lastik ve cam dahil değil."),DialogueTurn("C", "واضح وصادق. يومان بـ650 — اتفقنا؟", "Jelas dan jujur. Dua hari enam ratus lima puluh — deal?", "Açık ve dürüst. İki gün altı yüz elli — anlaştık mı?"),DialogueTurn("S", "اتفقنا! خريطة الطريق هدية — وسائق بلا عبء لاحقًا.", "Deal! Map gratis, kalau mau sewa besok tanpa driver lagi.", "Anlaştık! Hediye yol haritası — şoförsüz de gelirsiniz."))),
        Dialogue("dly-online", "مشكلة طلب أونلاين (إندونيسيا)", "وصل طلبك من متجر إلكتروني (Shopee/Tokopedia) ناقصًا قطعة. تتواصل مع البائع عبر محادثة المنصة.", Cefr.A1, listOf(DialogueTurn("C", "أهلًا. طلبي وصل ناقصًا — العلبة فيها قطعة واحدة بدل اثنتين.", "Halo kak. Pesanan saya kurang — di kotak cuma satu, yang saya pesan dua.", "Merhaba, siparişim eksik geldi — kutuda bir tane var, iki sipariş vermiştim."),DialogueTurn("S", "آسف جدًا! أرسل صورة العلبة والملصق.", "Maaf banget kak! Foto kotak sama labelnya kirim ya.", "Çok özür dileriz! Kutu ve etiketin fotoğrafını atın."),DialogueTurn("C", "أرسلت الصور مع رقم الطلب. ما الحل عندك؟", "Sudah saya kirim beserta nomor pesanan. Solusinya gimana kak?", "Foto ve sipariş numarası gitti. Çözümünüz ne?"),DialogueTurn("S", "خياران: أرسل القطعة اليوم بسرعة، أو استرد كاملًا.", "Dua pilihan: hari ini saya kirim yang kurang pakai kilat, atau uang kembali semua.", "İki seçenek: eksik parçayı bugün hızlı kargoyla yollayalım ya da tam iade."),DialogueTurn("C", "أرسلها اليوم — وأرجو تعويض شحن أي تعثر. عادل؟", "Kirim hari ini ya. Kalau telat, ongkir dikompensasi — adil kan?", "Bugün gönderin, gecikirse kargo bedeli компensasyon — adil mi?"),DialogueTurn("S", "عادل تمامًا — سأتابع الشحنة حتى بابك.", "Adil banget. Saya pantau kirimannya sampai depan pintu kak.", "Kesinlikle adil — kargonuzu kapınıza kadar takip edeceğim."),DialogueTurn("C", "شكرًا لسرعة تجاوبك — سأقيّمك خمسًا عند الوصول.", "Makasih responnya cepat kak. Bintang lima kalau sampai!", "Hızlı dönüşünüz için teşekkürler — ulaşınca beş yıldız."))),
        Dialogue("dly-invite", "دعوة عشاء واعتذار (إندونيسيا)", "جارك الإندونيسي دعاك لعشاء عائلي. تريد قبول الدعوة، وتحتاج أيضًا الاعتذار عن دعوة مقابلة لأصدقاء في وقت متقارب.", Cefr.A1, listOf(DialogueTurn("S", "أخي أحمد! غدًا مساءً عشاء عائلي بسيط عندنا — نشرّف بك.", "Mas Ahmed! Besok malam makan malam keluarga di rumah, sederhana aja. Meri bersama!", "Ahmed kardeşim! Yarın akşam evimizde sade bir aile yemeği — şeref verirsin."),DialogueTurn("C", "يشرفني! أحضر معي حلوى عربية — أصلها من بلادي.", "Dengan senang hati! Saya bawa kue Arab, dari kampung sendiri.", "Memnuniyetle! Yanına Arap tatlısı alırım, memleketimden."),DialogueTurn("S", "لا تتكلف! يكفي حضورك — هذا أجمل هدية.", "Jangan repot-repot! Yang penting dateng — itu sudah hadiah.", "Yorulma diye! Gelmeniz yeter — en güzel hediye bu."),DialogueTurn("C", "عاداتنا: لا نأتي بيدٍ فارغة أبدًا — اسمح لي.", "Tradisi kami: nggak pernah datang tangan kosong. Maklumin ya.", "Adetimiz: asla el boş gelmeyiz. Müsaadenizle."),DialogueTurn("S", "بارك الله فيك! الساعة 7 مساءً، مع أسرتك الصغيرة.", "Amin! Jam tujuh malam ya, bawa keluarga kecil sekalian.", "Amin! Saat yedide, küçük ailenizle beraber."),DialogueTurn("C", "سؤال أخير: أصدقائي دعوني غدًا أيضًا بعد العصر — أعتذر منهم بحضورك. أعذرني؟", "Satu lagi: teman-teman ngajak besok sore juga. Saya tolak pelan-pelan karena ke kakak. Boleh kan?", "Bir şey daha: arkadaşlarım da yarın davet etti. Sizin için nazikçe reddettim — sorun değil dimi?"),DialogueTurn("S", "تشرف الأولوية لي — وأصدقاؤك مدعوون معك للمرة القادمة!", "Kakak duluan ya! Lain kali ajak teman-temannya sekalian, saya senang.", "Öncelik bana ait! Başka sefere arkadaşlarınızı da getirin, sevinirim."))),
    ) }
    val stories: List<Story> by lazy { listOf(
        Story("sto-1", "صباح في السوق (Pagi di Pasar)", Cefr.A1, TargetLang.ID, "Pagi-pagi Ibu Ahmad pergi ke pasar. Dia mau beli sayur dan ikan. Di pasar ramai sekali. Penjual pertama berkata: \"Silakan, Bu, sayurnya segar!\" Ibu Ahmad bertanya: \"Ikan ini berapa?\" \"Lima puluh ribu, Bu.\" \"Mahal! Empat puluh ya?\" Penjual tersenyum: \"Ya sudah, empat puluh lima.\" Ibu Ahmad senang. Dia pulang dengan ikan dan sayur banyak.", "في الصباح الباكر تذهب أم أحمد إلى السوق. تريد شراء خضار وسمك. السوق مزدحم جدًا. البائع الأول يقول: «تفضلي سيدتي، خضارنا طازجة!» تسأل أم أحمد: «هذا السمك بكم؟» «خمسين ألفًا سيدتي.» «غالي! أربعين؟» يبتسم البائع: «حسنًا، خمسة وأربعين.» فرحت أم أحمد وعادت بسمكٍ وخضارٍ كثيرة.", listOf(QuizItem("sto-1-q", "ماذا أرادت أم أحمد أن تشتري؟", listOf("ملابس جديدة","خضار وسمك","فاكهة فقط"), 1, "", TargetLang.ID, "reading"),QuizItem("sto-1-q", "كيف ختمت المساومة؟", listOf("اشترت بأربعين","خرجت غاضبة","اشترت بخمسة وأربعين"), 2, "", TargetLang.ID, "reading"),QuizItem("sto-1-q", "ماذا يعني «ramai sekali»؟", listOf("مزدحم جدًا","هادئ جدًا","رخيص جدًا"), 0, "", TargetLang.ID, "reading"))),
        Story("sto-2", "زبون جديد (Langganan Baru)", Cefr.A2, TargetLang.ID, "Pak Rahman punya toko kecil di kampung. Suatu hari masuk pemuda baru. Dia cuma melihat-lihat. Pak Rahman tidak memaksa. Dia berkata: \"Pelan-pelan saja, kak. Lihat dulu.\" Pemuda itu senang hati. Dia bertanya tentang sepatu hitam. \"Yang ini kualitas bagus, tapi yang itu lebih murah,\" jelas Pak Rahman jujur. Pemuda itu kagum. \"Bapak jujur sekali.\" Akhirnya dia beli sepatu bagus itu. Sejak hari itu, dia jadi langganan. Dia juga mengajak teman-temannya. Toko Pak Rahman makin laris.", "يمتلك الرحمن دكانًا صغيرًا في الحي. يومًا دخل شاب جديد كان يتفرج فقط. لم يضغط عليه الرحمن، وقال: «على مهلك، تفرج أولًا.» ارتاح قلب الشاب وسأل عن حذاء أسود. «هذا جودته عالية وذلك أرخص،» شرح الرحمن بصدق. انبهر الشاب: «أنت صادق جدًا يا عمي!» أخيرًا اشترى الحذاء الجيد، وصار منذ ذلك اليوم زبونًا دائمًا، وجلب أصدقاءه معه، وصار دكان الرحمن أكثر رواجًا.", listOf(QuizItem("sto-2-q", "لماذا لم يضغط الرحمن على الشاب؟", listOf("لأنه مشغول","لأنه يفهم البيع الصادق","لأن الشاب فقير"), 1, "", TargetLang.ID, "reading"),QuizItem("sto-2-q", "ماذا فعل الشاب في النهاية؟", listOf("خرج بلا شراء","اشترى الأرخص","اشترى الجيد وصار زبونًا دائمًا"), 2, "", TargetLang.ID, "reading"),QuizItem("sto-2-q", "«Sejak hari itu» تعني:", listOf("في ذلك اليوم","منذ ذلك اليوم","قبل ذلك اليوم"), 1, "", TargetLang.ID, "reading"))),
        Story("sto-3", "دكان العم (Bakkal Amca)", Cefr.A1, TargetLang.TR, "Amca'nın bakkalı sabah erken açılır. Mahalleden insanlar gelir. \"Günaydın Amca!\" \"Günaydın komşum, hoş geldin!\" Ekmek, süt ve çay en çok satılan şeyler. Bir çocuk pencereye yaklaşır. \"Amca, bir sakız alabilir miyim?\" \"Tabii oğlum, al bakalım.\" Amca herkese güler yüzle bakar. Akşam dükkân kapanır. Amca tezgâhı siler. \"Yarın yine bekleriz,\" der.", "يُفتح دكان العم مبكرًا صباحًا، ويأتي أهل الحي: «صباح الخير يا عم!» «صباح الخير يا جاري، أهلًا بك!» الخبز والحليب والشاي أكثر الأشياء مبيعًا. يقترب طفل من الشباك: «يا عمي، أستطيع أن آخذ علكة؟» «طبعًا يا بني، خذ.» ينظر العم للجميع بوجه بشوش. في المساء يُغلق الدكان ويمسح العم الطاولة قائلًا: «غدًا ننتظركم من جديد.»", listOf(QuizItem("sto-3-q", "ما أكثر الأشياء مبيعًا في الدكان؟", listOf("الخبز والحليب والشاي","الحلويات","الجرايد"), 0, "", TargetLang.TR, "reading"),QuizItem("sto-3-q", "ماذا طلب الطفل؟", listOf("حليبًا","علكة","خبزًا"), 1, "", TargetLang.TR, "reading"),QuizItem("sto-3-q", "ماذا يقول العم عند الإغلاق؟", listOf("«الحمد لله انتهى اليوم»","«غدًا ننتظركم»","«الدكان مغلق للأبد»"), 1, "", TargetLang.TR, "reading"))),
        Story("sto-5", "سوق الليل (Pasar Malam)", Cefr.B1, TargetLang.ID, "Pasar malam baru saja buka. Lampu-lampu kecil menghiasi kios-kios. Pak Hasan menata buahnya dengan rapi. Di sebelahnya, mbak Rina menjual gorengan yang aromanya membuat semua orang lapar. Pelanggan pertama adalah ibu-ibu yang habis kerja. \"Bang, jeruk mana yang manis?\" tanya salah satunya. \"Semua manis, Bu. Tapi kalau mau yang paling, ambil yang ini. Coba dulu boleh,\" jawab Pak Hasan sambil tersenyum. Ibu itu mencoba, mengangguk, lalu membeli dua kilo. Semalaman Pak Hasan berjualan. Lelah, tapi hatinya senang. Rezeki malam itu cukup untuk sekolah anaknya.", "السوق الليلي افتتح للتو. أضواء صغيرة تزين الأكشاك. يرتب حسن فاكهته بعناية. وبجانبه تبيع رينا المقليات التي تجعل الجميع جائعًا من رائحتها. الزبائن الأوائل أمهات خرجن من العمل. «يا عمّ، أي البرتقال حلو؟» سألت إحداهن. «كله حلو يا سيدتي، لكن إن أردت الأحلى فخذ هذا — ذوق أولًا يجوز،» أجاب حسن مبتسمًا. ذاقت السيدة وأومأت ثم اشترت كيلوين. باع حسن طوال الليل. تعب لكن قلبه سعيد: رزق تلك الليلة كفى مدرسة ابنه.", listOf(QuizItem("sto-5-q", "كيف تعامل حسن مع سؤال «أيها أحلى؟»", listOf("قال كله سواء","عرض التذوق واقترح الأفضل","رفض الإجابة"), 1, "", TargetLang.ID, "reading"),QuizItem("sto-5-q", "لماذا كان قلب حسن سعيدًا رغم التعب؟", listOf("أغلق مبكرًا","رزق الليلة كفى مدرسة ابنه","باع أكشاكه"), 1, "", TargetLang.ID, "reading"),QuizItem("sto-5-q", "«menghiasi» تعني:", listOf("تزين","تشتري","تنظف"), 0, "", TargetLang.ID, "reading"))),
        Story("sto-6", "بائع البازار (Pazarcı Hasan)", Cefr.B1, TargetLang.TR, "Hasan Usta sabah beşte kalkmış; çünkü pazar günüymüş. Tezgâhını kurmuş, domatesleri dizerken ilk müşteri gelmiş. \"Abi, domatesler yerli mi?\" \"Yerli, Antalya'dan bu sabam geldi. Tatlı tatlı, ekmek arası ye!\" Müşteri gülümsemiş, iki kilo almış. Öğlene doğru fiyatlar düşmüş; çünkü akşamüstü mal bitmek istiyormuş. Hasan Usta seslenmiş: \"Son fiyat! Kalanlar gitsin, yarın taze gelsin!\" Bir kadın yaklaşmış: \"İki kilo alsam indirim olur mu?\" \"Olur mu olmaz mı — üç kilo alırsan olur!\" diye gülmüş. Akşam tezgâh boşalmış. Hasan Usta çayını yudumlarken düşünmüş: \"Yorulduk ama bereket var.\" Ertesi hafta aynı kadın yine gelmiş, bu sefer komşusunu da getirmiş.", "يُقال إن حسن أوستا استيقظ الخامسة فجرًا؛ لأن اليوم يوم سوق. نصب طاولته ورتب الطماطم فجاء أول زبون: «يا أخي، طماطمكم محلية؟» «محلية، جاءت من أنطاليا هذا الصباح — حلوة حلوة، كُلها بالخبز!» ابتسم الزبون وأخذ كيلوين. قرب الظهر هبطت الأسعار؛ لأن البضاعة كانت تريد النفاد قبل العصر. نادى حسن: «آخر سعر! ليذهب الباقي ويأتي الطازج غدًا!» اقتربت سيدة: «لو أخذت كيلوين ينفع خصم؟» ضاحكًا: «ينفع ولا لا — لو أخذت ثلاثة ينفع!» المساء: خلت الطاولة، وارتشف حسن شايه مفكرًا: «تعبنا لكن فيها بركة.» الأسبوع التالي عادت السيدة نفسها، وجاءت هذه المرة بجارتها أيضًا.", listOf(QuizItem("sto-6-q", "لماذا خفض حسن الأسعار قرب الظهر؟", listOf("البضاعة كانت ستنفد قبل العصر","الزبون غاضب","الطماطم فسدت"), 0, "", TargetLang.TR, "reading"),QuizItem("sto-6-q", "ماذا فعلت السيدة في الأسبوع التالي؟", listOf("لم تعد","عادت وجاءت بجارتها","اشتكت منه"), 1, "", TargetLang.TR, "reading"),QuizItem("sto-6-q", "«bereket var» تعني:", listOf("فيها خسارة","فيها بركة","فيها زحمة"), 1, "", TargetLang.TR, "reading"))),
        Story("sto-4", "السائح التائه (Kaybolan Turist)", Cefr.A2, TargetLang.TR, "Dün akşam bir turist sokakta durdu. Kaybolmuştu. Elinde bir harita vardı. Bakkaldaki Amca ona seslendi: \"Hoş geldiniz! Bir sorun mu var?\" Turist üzgün cevap verdi: \"Otelimi bulamıyorum.\" Amca haritaya baktı. \"Oteliniz çok yakın. Şu sokaktan düz gidin, sonra sola dönün. Beş dakika sürer.\" Turist çok mutlu oldu. \"Çok teşekkür ederim!\" \"Rica ederim. İyi tatiller!\" Ertesi gün turist yine geldi. Amcaya çikolata hediye etti. Artık her sabah \"Günaydın Amca!\" der.", "أمس مساءً وقف سائح في الشارع وقد ضلّ الطريق، وفي يده خريطة. ناداه العم من الدكان: «أهلًا بك! هل من مشكلة؟» أجاب السائح حزينًا: «لا أجد فندقي.» نظر العم إلى الخريطة: «فندقك قريب جدًا. امشِ مستقيمًا من ذلك الزقاق ثم استدر يسارًا — خمس دقائق.» فرح السائح: «شكرًا جزيلًا!» «العفو، إجازة سعيدة!» في اليوم التالي عاد السائح وأهدى العم شوكولاتة، ومنذها يقول كل صباح: «صباح الخير يا عمي!»", listOf(QuizItem("sto-4-q", "لماذا كان السائح حزينًا؟", listOf("فقد نقوده","ضلّ طريق فندقه","تأخرت طائرته"), 1, "", TargetLang.TR, "reading"),QuizItem("sto-4-q", "ما الاتجاهات التي أعطاها العم؟", listOf("مستقيمًا ثم يسارًا","يمينًا ثم يمينًا","مستقيمًا حتى النهاية"), 0, "", TargetLang.TR, "reading"),QuizItem("sto-4-q", "ماذا فعل السائح في اليوم التالي؟", listOf("غادر المدينة","اشتكى من العم","عاد بهدية وصار يلقي التحية يوميًا"), 2, "", TargetLang.TR, "reading"))),
        Story("sto-7", "مشكلة مع المورد (Masalah Pemasok)", Cefr.B1, TargetLang.ID, "Pak Bowo menelepon pemasoknya sore itu. \"Ibu Sari, pesanan kemarin kok beda warnanya?\" Di ujung telepon, Ibu Sari terdiam sejenak. \"Maaf Pak, tim gudang salah ambil. Saya ganti hari ini juga.\" Pak Bowo menarik napas. Pelanggannya menunggu, tapi dia tetap tenang. \"Baik Ibu, saya percaya. Tapi tolong, besok ada surat jalan yang benar.\" Keesokan harinya, barang yang benar datang lebih pagi dari janji. Di dalamnya ada kartu kecil: \"Terima kasih atas pengertiannya. Diskon 5% untuk pesanan berikutnya.\" Pak Bowo tersenyum. Dia mengerti: kesalahan bisa terjadi, tapi cara memperbaikinya yang menentukan hubungan. Bulan depan, dia justru menambah jumlah pesanannya.", "اتصل بوفو بمورّدته عصر ذلك اليوم: «سيدة ساري، طلب الأمس لماذا ألوانه مختلفة؟» صمتت ساري لحظة ثم قالت: «عذرًا، فريق المستودع أخطأ في الالتقاط — أستبدله اليوم نفسه.» تنفّس بوفو: زبونه ينتظر لكنه بقي هادئًا: «حسنًا أثق بكِ، لكن غدًا أريد سند شحن صحيحًا.» في اليوم التالي وصلت البضاعة الصحيحة أبكر من الموعد، وفي داخلها بطاقة صغيرة: «شكرًا لتفهمك — خصم 5% لطلبك القادم.» ابتسم بوفو: الأخطاء تحدث، لكن طريقة إصلاحها هي التي تحدد العلاقة. في الشهر التالي زاد طلبه بدل أن ينقص.", listOf(QuizItem("sto-7-q", "كيف ردّ بوفو على خطأ الموردة؟", listOf("بغضب وتهديد","بهدوء مع اشتراط تصحيح موثق","بإلغاء التعامل"), 1, "", TargetLang.ID, "reading"),QuizItem("sto-7-q", "ماذا فعلت الموردة في اليوم التالي؟", listOf("تجاهلت الطلب","أرسلت البضاعة أبكر مع بطاقة وخصم","طلبت اعتذارًا"), 1, "", TargetLang.ID, "reading"),QuizItem("sto-7-q", "ما نتيجة معالجة الأزمة بإحسان؟", listOf("قطع العلاقة","زيادة كمية الطلب الشهر التالي","خسارة الزبون"), 1, "", TargetLang.ID, "reading"))),
        Story("sto-8", "جمعة في البازار (Bazarda Cuma)", Cefr.B1, TargetLang.TR, "Cuma sabahı pazar kalabalıktı. Hasan Usta tezgâhını yeni dizmişti ki, Orta Doğu’dan bir aile yaklaştı. \"Hoş geldiniz! Bakın, taze incirler bugün geldi.\" Ailenin babası fiyat sordu, Hasan Usta rakam söyledi. Adam başını salladı ama ikna olmamıştı. O sırna ezan okundu. \"Buyurun,\" dedi Hasan Usta, \"namaz vakti. Dükkânım açık kalır, siz gidin rahatça gelin.\" Aile şaşırdı: \"Kapatmayacak mısınız?\" \"Müşterim kaybolmaz, güvendiğim insanlar geri döner.\" Aile namazdan döndüğünde tezgâh duruyordu, incirlerin en güzeli ayrıca poşetlenmişti. Baba gülümsedi: \"Bizi beklediniz demek?\" \"Ağırlamak bir beyefendi görevidir.\" O gün aile yalnız incir almadı; bir haftalık meyve ihtiyacını da Hasan Usta’dan karşıladı. Ve her cuma aynı tezgâh uğrak yeri oldu.", "صباح الجمعة كان البازار مزدحمًا. رتب حسن أوستا طاولته للتو حين اقتربت عائلة من الشرق الأوسط. «أهلًا بكم! تفضلوا، تين طازج وصل اليوم.» سأل الأب عن السعر فذكر حسن رقمًا، فأومأ الرجل غير مقتنع. عندها أذّن المؤذن. قال حسن: «تفضلوا، وقت الصلاة — دكاني يبقى مفتوحًا، اذهبوا وعودوا براحتكم.» تعجبت العائلة: «لن تغلق؟» «زبوني لا يضيع، من أثق به يعود.» حين عادت العائلة من الصلاة كانت الطاولة قائمة، وأجمل التين معبأ على حدة. ابتسم الأب: «انتظرتنا إذن؟» «الضيافة واجب أصيل.» ذلك اليوم لم تشترِ العائلة تينًا فقط، بل قالت حاجتها من الفاكهة لأسبوع كامل من حسن، وصارت كل جمعة مزارًا ثابتًا لطاولته.", listOf(QuizItem("sto-8-q", "ماذا فعل حسن عند الأذان؟", listOf("أغلق وذهب","أبقى الدكان مفتوحًا وطمأنهم","طلب منهم البقاء"), 1, "", TargetLang.TR, "reading"),QuizItem("sto-8-q", "ماذا فعلت العائلة بعد الصلاة؟", listOf("لم تعد","عادت واشترت حاجتها لأسبوع","اشتكت من الانتظار"), 1, "", TargetLang.TR, "reading"),QuizItem("sto-8-q", "الدرس التجاري للقصة:", listOf("الضغط يبيع","الثقة والضيافة تبنيان زبونًا دائمًا","الأسعار هي كل شيء"), 1, "", TargetLang.TR, "reading"))),
    ) }
